{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "id": {
            "type": "string"
        },
        "name": {
            "type": "string"
        },
        "type": {
            "type": "string"
        },
        "owner": {
            "type": "string"
        },
        "description": {
            "type": "string"
        },
        "vcsroot": {
            "type": "string"
        },
        "contact": {
            "type": "string"
        },
        "short_name": {
            "type": "string"
        },
        "tags": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "links": {
            "type": "object",
            "properties": {
                "homepage": {
                    "type": "string"
                },
                "buildchain": {
                    "type": "string"
                },
                "api_docs": {
                    "type": "string"
                }
            }
        },
        "service": {
            "type": "object",
            "properties": {
                "provides": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "description": {
                                "type": "string"
                            },
                            "service_name": {
                                "type": "string"
                            },
                            "protocol": {
                                "type": "string"
                            },
                            "port": {
                                "type": "integer"
                            },
                            "public_dns": {
                                "type": "array",
                                "items": {
                                    "type": "string"
                                }
                            },
                            "transport_protocol": {
                                "type": "string"
                            }
                        }
                    }
                },
                "depends_on": {
                    "type": "object",
                    "properties": {
                        "internal": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "short_name": {
                                        "type": "string"
                                    },
                                    "port": {
                                        "type": "integer"
                                    }
                                }
                            }
                        },
                        "external": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "target": {
                                        "type": "string"
                                    },
                                    "transport_protocol": {
                                        "type": "string"
                                    },
                                    "why": {
                                        "type": "string"
                                    }
                                }
                            }
                        }
                    }
                }
            }
