        "context": {
            "type": "object",
            "properties": {
                "belongs_to_bounded_context": {
                    "type": "string"
                },
                "visibility": {
                    "type": "string"
                }
            }
        },
        "runtime": {
            "type": "object",
            "properties": {
                "cpu": {
                    "type": "string"
                },
                "ram": {
                    "type": "string"
                },
                "disk": {
                    "type": "string"
                },
                "host_type": {
                    "type": "string"
                },
                "network_zone": {
                    "type": "string"
                }
            }
        },
        "software_dependencies": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "name": {
                        "type": "string"
                    },
                    "version": {
                        "type": "string"
                    },
                    "licenses": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "name": {
                                    "type": "string"
                                },
                                "url": {
                                    "type": "string"
                                }
                            }
                        }
                    }
                }
            }
        }
    },
    "required": [
        "id",
        "name",
        "type",
        "owner",
        "description"
    ]
