{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Payment Event Fields Schema",
    "description": "Defines the event fields our system recognizes as a purchase event",
    "type": "object",
    "properties": {
        "checkout_id": {
            "type": "string",
            "title": "Checkout ID",
            "description": "The checkout ID associated with this purchase",
            "maxLength": 375
        },
        "order_id": {
            "type": "string",
            "title": "Order ID",
            "description": "The order or transaction ID associated with this purchase",
            "maxLength": 375
        },
        "affiliation": {
            "type": "string",
            "title": "Affiliation",
            "description": "Store or affiliation from which this transaction occurred (e.g. Google Store)",
            "maxLength": 375
        },
        "subtotal": {
            "type": "number",
            "title": "Purchase Subtotal",
            "minimum": 0,
            "description": "Order total after discounts but before taxes and shipping"
        },
        "total": {
            "type": "number",
            "title": "Purchase Total",
            "minimum": 0,
            "description": "Revenue with discounts and coupons added in"
        },
        "revenue": {
            "type": "number",
            "title": "Revenue",
            "minimum": 0,
            "description": "Revenue associated with the transaction (excluding shipping and tax). This is the field we use to calculate a customer's LTV."
        },
        "shipping": {
            "type": "number",
            "title": "Shipping Cost",
            "minimum": 0,
            "description": "Shipping cost associated with the transaction"
        },
        "tax": {
            "type": "number",
            "title": "Total Tax",
            "minimum": 0,
            "description": "Total tax associated with the transaction"
        },
        "discount": {
            "type": "number",
            "title": "Discount",
            "minimum": 0,
            "description": "Total discount associated with the transaction"
        },
        "coupon": {
            "type": "string",
            "title": "Coupon",
            "description": "Transaction coupon redeemed with the transaction",
            "maxLength": 375
        },
        "currency": {
            "type": "string",
            "title": "Currency",
            "description": "The ISO currency code used in this purchase",
            "pattern": "^[A-Z]{3}$"
        },
        "products": {
            "type": "array",
            "title": "Products",
            "maxItems": 200,
            "items": {
                "$ref": "#/definitions/product"
            }
        }
    },
    "additionalProperties": false,
    "definitions": {
        "product": {
            "type": "object",
            "properties": {
                "product_id": {
                    "type": "string",
                    "title": "Product ID",
                    "description": "Database id of the product being viewed",
                    "maxLength": 375
                },
                "sku": {
                    "type": "string",
                    "title": "Stock Keeping Unit",
                    "description": "Sku of the product being viewed",
                    "maxLength": 375
                },
                "category": {
                    "type": "string",
                    "title": "Product Category",
                    "description": "Product category being viewed",
                    "maxLength": 375
                },
                "name": {
                    "type": "string",
                    "title": "Product Name",
                    "description": "Name of the product being viewed",
                    "maxLength": 375
                },
                "brand": {
                    "type": "string",
                    "title": "Brand",
                    "description": "Brand associated with the product",
                    "maxLength": 375
                },
                "variant": {
                    "type": "string",
                    "title": "Product Variant",
                    "description": "Variant of the product (e.g. Black)",
                    "maxLength": 375
                },
                "price": {
                    "type": "number",
                    "title": "Price",
                    "description": "Price of the product being viewed",
                    "minimum": 0
                },
                "quantity": {
                    "type": "integer",
                    "title": "Quantity",
                    "description": "Quantity of a product",
                    "minimum": 0
                },
                "coupon": {
                    "type": "string",
                    "title": "Coupon",
                    "description": "Coupon code associated with a product (e.g MAY_DEALS_3)",
                    "maxLength": 375
                },
                "position": {
                    "type": "integer",
                    "title": "Product Position",
                    "description": "Position in the product list (ex. 3)"
                },
                "url": {
                    "type": "string",
                    "title": "Product URL",
                    "description": "URL of the product page",
                    "maxLength": 375
                },
                "image_url": {
                    "type": "string",
                    "title": "Image URL",
                    "description": "Image url of the product",
                    "maxLength": 375
                }
            },
            "required": [
                "product_id"
            ],
            "additionalProperties": false
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema",
    "description": "JSON Schema for droplit-edge localsettings",
    "definitions": {
        "plugins-array": {
            "type": "array",
            "items": {
                "oneOf": [
                    {
                        "type": "string"
                    },
                    {
                        "$ref": "#/definitions/plugins-array-item"
                    }
                ]
            }
        },
        "plugins-array-item": {
            "description": "Configuration for an individual plugin.",
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "enabled": {
                    "description": "Set whether the plugin is enabled.",
                    "type": "boolean",
                    "default": true
                },
                "localServices": {
                    "description": "List local services that the plugin manages.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    },
                    "_uniqueItems": true
                },
                "name": {
                    "description": "The name of the plugin.",
                    "type": "string"
                }
            },
            "required": [
                "name"
            ]
        },
        "plugins-object": {
            "description": "Configuration for an individual plugin.",
            "type": "object",
            "additionalProperties": {
                "type": "object",
                "properties": {
                    "enabled": {
                        "description": "Set whether the plugin is enabled.",
                        "type": "boolean",
                        "default": true
                    },
                    "localServices": {
                        "description": "List local services that the plugin manages.",
                        "type": "array",
                        "items": {
                            "type": "string"
                        },
                        "_uniqueItems": true
                    }
                }
            }
        }
    },
    "type": "object",
    "additionalProperties": false,
    "properties": {
        "config": {
            "description": "Configures miscellaneous capabilities.",
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "LinuxNetInterfaceOverride": {
                    "description": "Override the Linux network interface",
                    "type": "string"
                },
                "MACAddressOverride": {
                    "description": "Override the MAC address used as the Edge Id.",
                    "type": "string"
                },
                "provisioningServiceEnabled": {
                    "description": "Enables the network provisioning service.",
                    "type": "boolean"
                },
                "provisioningServicePort": {
                    "description": "Set the port used for network provisioning.",
                    "type": "integer",
                    "minimum": 0,
                    "maximum": 65536,
                    "default": 81
                }
            }
        },
        "debug": {
            "description": "Configures debugging options.",
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "generateHeapDump": {
                    "description": "Periodically generate a heap dump file.",
                    "type": "boolean"
                },
                "logToFile": {
                    "description": "Whether to log out to a file.",
                    "type": "boolean",
                    "default": true
                },
                "logPath": {
                    "description": "The file path to the file log.",
                    "type": "string"
                }
            }
        },
        "diagnostics": {
            "description": "Configures the diagnostics telnet console.",
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "enabled": {
                    "description": "Determine whether the console should be enabled or not.",
                    "type": "boolean"
                },
                "port": {
                    "description": "The port the console is opened on.",
                    "type": "integer",
                    "minimum": 0,
                    "maximum": 65536,
                    "default": 8888
                }
            }
        },
        "ecosystemId": {
            "description": "The Ecosystem associated with this Edge device. May be omitted if Ecosystem is determined via the claims process.",
            "type": "string"
        },
        "environmentId": {
            "description": "The Environment associated with this Edge device. Specifying this allows for multiple Edge devices within the same environment.",
            "type": "string"
        },
        "router": {
            "description": "Configures the Edge router layer.",
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "autodiscover": {
                    "description": "Whether or not autodiscover should be enabled.",
                    "type": "boolean"
                },
                "autodiscoverCadence": {
                    "description": "The amount of time (in ms) between discovery invocations.",
                    "type": "integer",
                    "minimum": 0
                }
            }
        },
        "plugins": {
            "oneOf": [
                {
                    "$ref": "#/definitions/plugins-object"
                },
                {
                    "$ref": "#/definitions/plugins-array"
                }
            ]
        },
        "transport": {
            "description": "Configures the Edge transport layer.",
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "enableHeartbeat": {
                    "description": "Whether or not heartbeat should be enabled. This should only ever be disabled for diagnostic purposes.",
                    "type": "boolean",
                    "default": true
                },
                "host": {
                    "description": "The host service uri.",
                    "type": "string",
                    "format": "uri"
                }
            }
        }
    },
    "default": {},
    "required": [
        "transport"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "JSON Schema for Common Vulnerability Scoring System version 3.x",
    "id": "https://scap.nist.gov/schema/nvd/feed/1.1/cvss-v3.x.json",
    "type": "object",
    "definitions": {
        "attackVectorType": {
            "type": "string",
            "enum": [
                "NETWORK",
                "ADJACENT_NETWORK",
                "LOCAL",
                "PHYSICAL"
            ]
        },
        "modifiedAttackVectorType": {
            "type": "string",
            "enum": [
                "NETWORK",
                "ADJACENT_NETWORK",
                "LOCAL",
                "PHYSICAL",
                "NOT_DEFINED"
            ]
        },
        "attackComplexityType": {
            "type": "string",
            "enum": [
                "HIGH",
                "LOW"
            ]
        },
        "modifiedAttackComplexityType": {
            "type": "string",
            "enum": [
                "HIGH",
                "LOW",
                "NOT_DEFINED"
            ]
        },
        "privilegesRequiredType": {
            "type": "string",
            "enum": [
                "HIGH",
                "LOW",
                "NONE"
            ]
        },
        "modifiedPrivilegesRequiredType": {
            "type": "string",
            "enum": [
                "HIGH",
                "LOW",
                "NONE",
                "NOT_DEFINED"
            ]
        },
        "userInteractionType": {
            "type": "string",
            "enum": [
                "NONE",
                "REQUIRED"
            ]
        },
        "modifiedUserInteractionType": {
            "type": "string",
            "enum": [
                "NONE",
                "REQUIRED",
                "NOT_DEFINED"
            ]
        },
        "scopeType": {
            "type": "string",
            "enum": [
                "UNCHANGED",
                "CHANGED"
            ]
        },
        "modifiedScopeType": {
            "type": "string",
            "enum": [
                "UNCHANGED",
                "CHANGED",
                "NOT_DEFINED"
            ]
        },
        "ciaType": {
            "type": "string",
            "enum": [
                "NONE",
                "LOW",
                "HIGH"
            ]
        },
        "modifiedCiaType": {
            "type": "string",
            "enum": [
                "NONE",
                "LOW",
                "HIGH",
                "NOT_DEFINED"
            ]
        },
        "exploitCodeMaturityType": {
            "type": "string",
            "enum": [
                "UNPROVEN",
                "PROOF_OF_CONCEPT",
                "FUNCTIONAL",
                "HIGH",
                "NOT_DEFINED"
            ]
        },
        "remediationLevelType": {
            "type": "string",
            "enum": [
                "OFFICIAL_FIX",
                "TEMPORARY_FIX",
                "WORKAROUND",
                "UNAVAILABLE",
                "NOT_DEFINED"
            ]
        },
        "confidenceType": {
            "type": "string",
            "enum": [
                "UNKNOWN",
                "REASONABLE",
                "CONFIRMED",
                "NOT_DEFINED"
            ]
        },
        "ciaRequirementType": {
            "type": "string",
            "enum": [
                "LOW",
                "MEDIUM",
                "HIGH",
                "NOT_DEFINED"
            ]
        },
        "scoreType": {
            "type": "number",
            "minimum": 0,
            "maximum": 10
        },
        "severityType": {
            "type": "string",
            "enum": [
                "NONE",
                "LOW",
                "MEDIUM",
                "HIGH",
                "CRITICAL"
            ]
        }
    },
    "properties": {
        "version": {
            "description": "CVSS Version",
            "type": "string",
            "enum": [
                "3.0",
                "3.1"
            ]
        },
        "vectorString": {
            "type": "string",
            "pattern": "^CVSS:3.[01]/((AV:[NALP]|AC:[LH]|PR:[UNLH]|UI:[NR]|S:[UC]|[CIA]:[NLH]|E:[XUPFH]|RL:[XOTWU]|RC:[XURC]|[CIA]R:[XLMH]|MAV:[XNALP]|MAC:[XLH]|MPR:[XUNLH]|MUI:[XNR]|MS:[XUC]|M[CIA]:[XNLH])/)*(AV:[NALP]|AC:[LH]|PR:[UNLH]|UI:[NR]|S:[UC]|[CIA]:[NLH]|E:[XUPFH]|RL:[XOTWU]|RC:[XURC]|[CIA]R:[XLMH]|MAV:[XNALP]|MAC:[XLH]|MPR:[XUNLH]|MUI:[XNR]|MS:[XUC]|M[CIA]:[XNLH])$"
        },
        "attackVector": {
            "$ref": "#/definitions/attackVectorType"
        },
        "attackComplexity": {
            "$ref": "#/definitions/attackComplexityType"
        },
        "privilegesRequired": {
            "$ref": "#/definitions/privilegesRequiredType"
        },
        "userInteraction": {
            "$ref": "#/definitions/userInteractionType"
        },
        "scope": {
            "$ref": "#/definitions/scopeType"
        },
        "confidentialityImpact": {
            "$ref": "#/definitions/ciaType"
        },
        "integrityImpact": {
            "$ref": "#/definitions/ciaType"
        },
        "availabilityImpact": {
            "$ref": "#/definitions/ciaType"
        },
        "baseScore": {
            "$ref": "#/definitions/scoreType"
        },
        "baseSeverity": {
            "$ref": "#/definitions/severityType"
        },
        "exploitCodeMaturity": {
            "$ref": "#/definitions/exploitCodeMaturityType"
        },
        "remediationLevel": {
            "$ref": "#/definitions/remediationLevelType"
        },
        "reportConfidence": {
            "$ref": "#/definitions/confidenceType"
        },
        "temporalScore": {
            "$ref": "#/definitions/scoreType"
        },
        "temporalSeverity": {
            "$ref": "#/definitions/severityType"
        },
        "confidentialityRequirement": {
            "$ref": "#/definitions/ciaRequirementType"
        },
        "integrityRequirement": {
            "$ref": "#/definitions/ciaRequirementType"
        },
        "availabilityRequirement": {
            "$ref": "#/definitions/ciaRequirementType"
        },
        "modifiedAttackVector": {
            "$ref": "#/definitions/modifiedAttackVectorType"
        },
        "modifiedAttackComplexity": {
            "$ref": "#/definitions/modifiedAttackComplexityType"
        },
        "modifiedPrivilegesRequired": {
            "$ref": "#/definitions/modifiedPrivilegesRequiredType"
        },
        "modifiedUserInteraction": {
            "$ref": "#/definitions/modifiedUserInteractionType"
        },
        "modifiedScope": {
            "$ref": "#/definitions/modifiedScopeType"
        },
        "modifiedConfidentialityImpact": {
            "$ref": "#/definitions/modifiedCiaType"
        },
        "modifiedIntegrityImpact": {
            "$ref": "#/definitions/modifiedCiaType"
        },
        "modifiedAvailabilityImpact": {
            "$ref": "#/definitions/modifiedCiaType"
        },
        "environmentalScore": {
            "$ref": "#/definitions/scoreType"
        },
        "environmentalSeverity": {
            "$ref": "#/definitions/severityType"
        }
    },
    "required": [
        "version",
        "vectorString",
        "baseScore",
        "baseSeverity"
    ]
}

{
    "type": "object",
    "$schema": "http://json-schema.org/draft-07/schema",
    "definitions": {
        "actionObject": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string"
                },
                "exec": {
                    "oneOf": [
                        {
                            "type": "string"
                        },
                        {
                            "$ref": "#/definitions/functionObject"
                        }
                    ]
                }
            },
            "required": [
                "type"
            ]
        },
        "baseStateNode": {
            "type": "object",
            "properties": {
                "id": {
                    "type": "string"
                },
                "key": {
                    "type": "string"
                },
                "type": {
                    "type": "string",
                    "enum": [
                        "atomic",
                        "compound",
                        "parallel",
                        "final",
                        "history"
                    ]
                },
                "order": {
                    "$ref": "#/definitions/order"
                }
            },
            "required": [
                "id",
                "key",
                "type"
            ]
        },
        "compoundStateNode": {
            "allOf": [
                {
                    "$ref": "#/definitions/baseStateNode"
                },
                {
                    "type": "object",
                    "properties": {
                        "type": {
                            "type": "string",
                            "pattern": "compound"
                        },
                        "entry": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/actionObject"
                            }
                        },
                        "exit": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/actionObject"
                            }
                        },
                        "initial": {
                            "type": "string"
                        },
                        "invoke": {
                            "$ref": "#/definitions/invokeArray"
                        },
                        "on": {
                            "$ref": "#/definitions/transitionsObject"
                        },
                        "states": {
                            "$ref": "#/definitions/statesObject"
                        }
                    },
                    "required": [
                        "states"
                    ]
                }
            ]
        },
        "parallelStateNode": {
            "allOf": [
                {
                    "$ref": "#/definitions/baseStateNode"
                },
                {
                    "type": "object",
                    "properties": {
                        "type": {
                            "type": "string",
                            "pattern": "parallel"
                        },
                        "entry": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/actionObject"
                            }
                        },
                        "exit": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/actionObject"
                            }
                        },
                        "invoke": {
                            "$ref": "#/definitions/invokeArray"
                        },
                        "on": {
                            "$ref": "#/definitions/transitionsObject"
                        },
                        "states": {
                            "$ref": "#/definitions/statesObject"
                        }
                    },
                    "required": [
                        "states"
                    ]
                }
            ]
        },
        "atomicStateNode": {
            "allOf": [
                {
                    "$ref": "#/definitions/baseStateNode"
                },
                {
                    "type": "object",
                    "properties": {
                        "type": {
                            "type": "string",
                            "pattern": "atomic"
                        },
                        "entry": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/actionObject"
                            }
                        },
                        "exit": {
                            "type": "array",
                            "items": {
                                "$ref": "#/definitions/actionObject"
                            }
                        },
                        "invoke": {
                            "$ref": "#/definitions/invokeArray"
                        },
                        "on": {
                            "$ref": "#/definitions/transitionsObject"
                        }
                    },
                    "required": [
                        "on"
                    ]
                }
            ]
        },
        "historyStateNode": {
            "allOf": [
                {
                    "$ref": "#/definitions/baseStateNode"
                },
                {
                    "type": "object",
                    "properties": {
                        "type": {
                            "type": "string",
                            "pattern": "history"
                        },
                        "history": {
                            "type": "string",
                            "enum": [
                                "shallow",
                                "deep"
                            ]
                        }
                    },
                    "required": [
                        "history"
                    ]
                }
            ]
        },
        "finalStateNode": {
            "allOf": [
                {
                    "$ref": "#/definitions/baseStateNode"
                },
                {
                    "type": "object",
                    "properties": {
                        "type": {
                            "type": "string",
                            "pattern": "final"
                        },
                        "data": {
                            "type": "object"
                        }
                    }
                }
            ]
        },
        "statesObject": {
            "type": "object",
            "patternProperties": {
