                        "pattern": "^(browser|node|rhino)$",
                        "default": "browser"
                    },
                    "loaderTemplate": {
                        "description": "The boot loader template file, usually determined automatically from the application type",
                        "type": "string"
                    },
                    "default": {
                        "description": "If true, this application is considered the default when serving the application; if not provided then the first browser app is the default application. When applications are generated, each application has it's own directory inside the target directory and also has it's own index.html. However, there is an index.html which is generated in the target output directory that runs the `default` application.",
                        "type": "boolean"
                    },
                    "parts": {
                        "$ref": "#/properties/parts"
                    },
                    "minify": {
                        "$ref": "#/properties/targets"
                    },
                    "save-source-in-map": {
                        "$ref": "#/properties/targets"
                    },
                    "save-unminified": {
                        "$ref": "#/properties/targets"
                    }
                }
            }
        },
        "targets": {
            "type": "array",
            "minItems": 1,
            "items": {
                "type": "object",
                "required": [
                    "type",
                    "outputPath"
                ],
                "additionalProperties": false,
                "properties": {
                    "type": {
                        "description": "Either `source`, `build`, or a class name in qooxdoo-compiler; using a class name is advanced usage, but ultimately the standard names just shortcuts to class names anyway (`source` is `qx.tool.compiler.targets.SourceTarget`, etc)",
                        "type": "string"
                    },
                    "description": {
                        "description": "A description of the target's function.",
                        "type": "string"
                    },
                    "application-types": {
                        "description": "The application types which this target supports",
                        "type": "array",
                        "items": {
                            "type": "string",
                            "pattern": "^(browser|node|rhino)$"
                        }
                    },
                    "application-names": {
                        "description": "The application names which this target supports",
                        "type": "array",
                        "items": {
                            "type": "string"
                        }
                    },
                    "outputPath": {
                        "description": "The folder where the compilation outputs to, and will be created if it does not already exist",
                        "type": "string"
                    },
                    "deployPath": {
                        "description": "The folder where the deploy outputs to.",
                        "type": "string"
                    },
                    "targetClass": {
                        "description": "If you want to use more than the two default target types and/or use custom target classes, you can use the targetClass key to supply the name of the class as a string.",
                        "type": "string"
                    },
                    "bundle": {
                        "$ref": "#/properties/bundle"
                    },
                    "uri": {
                        "description": "this sets the URI used to access the target output directory, i.e. the directory which will contain resources/ and transpiled/",
                        "type": "string"
                    },
                    "environment": {
                        "$ref": "#/properties/environment"
                    },
                    "writeCompileInfo": {
                        "description": "if true, the target will write a compile-info.json and resources.json into the application's output directory, containing the data structures required to generate an application",
                        "type": "boolean"
                    },
                    "typescript": {
                        "type": [
                            "boolean",
                            "string"
                        ],
                        "description": "When true, output the typescript definition into ``./compiled/source/qooxdoo.d.ts`. If you use a string instead of true, the string is the name of the file which is generated inside the target output directory"
                    },
                    "minify": {
                        "description": "Determines the minification to be used for applications, if the target supports it. Can be off, minify, mangle, or beautify. Can be overridden on a per application basis.",
                        "type": "string",
                        "pattern": "^(off|minify|mangle|beautify)$"
                    },
                    "deploy-source-maps": {
                        "description": "If true, the source maps will be deployed.",
                        "type": "boolean"
                    },
                    "save-source-in-map": {
                        "description": "If true, the source file will be saved in the map file if the target supports it. Can be overridden on a per application basis.",
                        "type": "boolean"
                    },
                    "save-unminified": {
                        "description": "If true, the unminified files will be saved if the target supports it. Can be overridden on a per application basis.",
                        "type": "boolean"
                    },
                    "addCreatedAt": {
                        "description": "If true, this will cause every object to have a hidden property called $$createdAt which points to an object containing filename, lineNumber, and column properties.",
                        "type": "boolean"
                    },
                    "babelOptions": {
                        "type": "object",
                        "description": "Options given to @babel/preset-env. With this options the output type of babel can be defined. For details see here: <https://babeljs.io/docs/en/babel-preset-env#options>. They can be overridden per target."
                    },
                    "parts": {
                        "$ref": "#/properties/parts"
                    }
                }
            }
        },
        "defaultTarget": {
            "type": "string",
            "pattern": "^(build|source)$"
        },
        "libraries": {
            "description": "If you don't specify a libraries key, then by default the current directory will be used (provided that there is a Manifest.json file) as a library; this makes sense for most applications.",
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "include": {
            "description": "An array of class names which are to be included in the compilation, regardless of whether the compiler can detect if they are needed (for example, your application dynamically choose class names on the fly). Wildcards are supported by adding a *.",
            "type": "array",
            "_uniqueItems": true,
            "examples": [
                "qx.util.format.*"
            ],
            "items": {
                "type": "string"
            }
        },
        "exclude": {
            "description": "An array of class names which are to be excluded from the application, regardless of whether the compiler thinks that they are needed. Wildcards are supported by adding a *. Note that exclude takes priority over include",
            "type": "array",
            "_uniqueItems": true,
            "examples": [
                "qx.util.format.NumberFormat"
            ],
            "items": {
                "type": "string"
            }
        },
        "parts": {
            "description": "Each part has an include array which is a list of classes (including wildcards) that are to be included.",
            "type": "object",
            "patternProperties": {
                "^\\S+$": {
                    "required": [
                        "include"
                    ],
                    "additionalProperties": false,
                    "properties": {
                        "include": {
                            "description": "A list of class glob patterns to include in this part.",
                            "type": "array",
                            "items": {
                                "type": "string"
                            }
                        },
                        "exclude": {
                            "description": "A list of class glob patterns to exclude from this part.",
                            "type": "array",
                            "items": {
                                "type": "string"
                            }
                        }
                    }
                }
            }
        },
        "path-mappings": {
            "description": " generic means to locate files on disk inside the URI address space of the application",
            "type": "object",
            "patternProperties": {
                "^\\S+$": {
                    "description": "virtual path as seen from the browser",
                    "type": "string"
                }
            },
            "examples": [
                {
                    "../qooxdoo": "/some/virtual/uri/path/qooxdoo"
                }
            ]
        },
        "locales": {
            "description": "Include other translations than 'en'",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1,
                "//pattern": "^\\S+$"
            }
        },
        "i18nAsParts": {
            "description": "Whether to store locales and translations as individual parts, which are manually loaded on demand by the application",
            "type": "boolean"
        },
        "writeAllTranslations": {
            "description": "By default, only translation strings which are used by the classes are included into the application.",
            "type": "boolean"
        },
        "serve": {
            "type": "object",
            "description": "Configure the qx compilers built-in webserver",
            "additionalProperties": false,
            "properties": {
                "listenPort": {
                    "type": "integer"
                }
            }
        },
        "environment": {
            "type": "object",
            "patternProperties": {
                "^\\S+$": {
                    "description": "This will show up in `qx.core.Environment`"
                }
            }
        },
        "ignores": {
            "description": "An array of names which the compiler should ignore. Same as @ignore in source code",
            "type": "array",
            "_uniqueItems": true,
            "examples": [
                "modules.*"
            ],
            "items": {
                "type": "string"
            }
        },
        "babel": {
            "type": "object",
            "properties": {
                "options": {
                    "type": "object",
                    "description": "Options given to @babel/preset-env. With this options the output type of babel can be defined. For details see here: <https://babeljs.io/docs/en/babel-preset-env#options>. They can be overridden per target."
                },
                "plugins": {
                    "type": "object",
                    "description": "List of additional babel plugins to enable, eg TC39 proposals; note that some proposals will work out of the box and some will require upgrades to QxCompiler before they work properly - your mileage may vary.  Each key in this object is the NPM name of the plugin, and the value is either true (enabled), false (ignore), or an object which is options to pass to the preset",
                    "additionalProperties": {
                        "type": [
                            "boolean",
                            "object"
                        ]
                    }
                }
            }
        },
        "babelOptions": {
            "type": "object",
            "description": "** DEPRECATED - See babel.options instead",
            "deprecated": true
        },
        "jsx": {
            "type": "object",
            "description": "Options given to @babel/preset-react to change how JSX HTML is transpiled"
        },
        "eslintConfig": {
            "type": "object",
            "description": "The syntax is the same as in in package.json. Explanation can be found here: <https://eslint.org/docs/user-guide/configuring>"
        },
        "bundle": {
            "description": "Allows you to use wildcards to select classes which are to be bundled together into as few files as possible",
            "type": "object",
            "properties": {
                "include": {
                    "description": "An array of namespaces to include in the bundle. Can contain wildcards.",
                    "type": [
                        "array",
                        "string"
                    ],
                    "items": {
                        "type": "string"
                    }
                },
                "exclude": {
                    "description": "An array of namespaces to exclude from the bundle. Can contain wildcards.",
                    "type": [
                        "array",
                        "string"
                    ],
                    "items": {
                        "type": "string"
                    }
                }
            }
        }
    }
}

{
    "$id": "http://example.com/root.json",
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "title": "turbosite.json schema",
    "required": [
        "$schema",
        "errorSetup",
        "homeView",
        "baseURL",
        "singleParameterView",
        "locales",
        "translationLocations",
        "globalCDNS",
        "globalJs",
        "globalCss",
        "globalComponents",
        "globalHtml",
        "viewComponents",
        "webServices"
    ],
    "additionalProperties": false,
    "properties": {
        "$schema": {
            "type": "string",
            "description": "Url to the json schema definition to validate this file",
            "enum": [
                "https://raw.githubusercontent.com/edertone/TurboBuilder/master/TurboBuilder-Node/src/main/resources/json-schema/turbosite.schema.json"
            ]
        },
        "errorSetup": {
            "type": "object",
            "description": "Defines how errors and warnings are handled by the application",
            "required": [
                "exceptionsToBrowser",
                "exceptionsToLog",
                "exceptionsToMail",
                "warningsToBrowser",
                "warningsToLog",
                "warningsToMail",
                "tooMuchTimeWarning",
                "tooMuchMemoryWarning"
            ],
            "additionalProperties": false,
            "properties": {
                "exceptionsToBrowser": {
                    "type": "boolean",
                    "description": "If set to true, all application exceptions information will be written directly to the browser output."
                },
                "exceptionsToLog": {
                    "type": "string",
                    "description": "A log filename or relative path where the exceptions must be written. If not specified, no log will be output. The filename or relative path must be based on the depot logs setup"
                },
                "exceptionsToMail": {
                    "type": "string",
                    "description": "The Exceptionstomail Schema"
                },
                "warningsToBrowser": {
                    "type": "boolean",
                    "description": "The Warningstobrowser Schema"
                },
                "warningsToLog": {
                    "type": "string",
                    "description": "A log filename or relative path where the warnings must be written. If not specified, no log will be output. The filename or relative path must be based on the depot logs setup"
                },
                "warningsToMail": {
                    "type": "string",
                    "description": "The Warningstomail Schema"
                },
                "tooMuchTimeWarning": {
                    "type": "integer",
                    "description": "When running time on any of the site urls exceeds the number of miliseconds defined here, a warning will be launched. If set to zero, this feature will be disabled"
                },
                "tooMuchMemoryWarning": {
                    "type": "integer",
                    "description": "When allocated memory on any of the site urls exceeds the number of bytes defined here, a warning will be launched. If set to zero, this feature will be disabled"
                }
            }
        },
        "homeView": {
            "type": "string",
            "description": "Contains the name of the view that is used by the root url. Leave it empty if there's no home view",
            "examples": [
                "home",
                "some-other-view"
            ]
        },
        "baseURL": {
            "type": "string",
            "description": "If the project is not deployed at the root of its host, we must place here the relative path where it is located. For example, if we deploy our site into http://somehost.com/somefolder, we must define the baseURL as \"somefolder\""
        },
        "singleParameterView": {
            "type": "string",
            "description": "This is the view that will be called by default when the current url contains only a single parameter like: http://host/this-is-a-parameter. Leave it empty if there's no single parameter view"
        },
        "locales": {
            "type": "array",
            "description": "The list of locales that will be available on the site. Sorted by preference",
            "items": {
                "type": "string"
            }
        },
        "translationLocations": {
            "type": "array",
            "description": "List of locations where the resource bundles containing the site translation are located. Each array item must be an object with three properties: label, path and bundles.",
            "items": {
                "type": "object",
                "required": [
                    "label",
                    "path",
                    "bundles"
                ],
                "additionalProperties": false,
                "properties": {
                    "label": {
                        "type": "string",
                        "description": "The name that is used to define the translations location, so it can be referenced when requesting a translation",
                        "examples": [
                            "resources-locales"
                        ]
                    },
                    "path": {
                        "type": "string",
                        "description": "A path relative to src/main that defines the file structure to reach the translation files inside a folder. Wilcards must be used for $bundle and $locale",
                        "examples": [
                            "resources/locales/$bundle/$bundle_$locale.properties"
                        ]
                    },
                    "bundles": {
                        "type": "array",
                        "description": "The list of bundles that will be initially loaded from the provided path. This list can be empty here and bundles added later as required.",
                        "examples": [
                            "home",
                            "footer"
                        ]
                    }
                }
            }
        },
        "globalCDNS": {
            "type": "array",
            "description": "List of js files that will be loaded from CDN urls. These files are loaded first on the view documents, before any other global js files. They will be loaded in the same order as provided here. Each array item must be an object with 3 properties: url (direct url to the CDN file), fallbackVerify (a sentence that must evaluate to true to check that CDN is correctly loaded) and fallbackResource (A path inside src/main to load the local CDN file if remote not possible)",
            "items": {
                "type": "object",
                "description": "The Items Schema",
                "required": [
                    "url",
                    "fallbackVerify",
                    "fallbackResource"
                ],
                "additionalProperties": false,
                "properties": {
                    "url": {
                        "type": "string",
                        "description": "The Url Schema",
                        "examples": [
                            "https://ajax.googleapis.com/ajax/libs/jquery/3.3.1/jquery.min.js"
                        ]
                    },
                    "fallbackVerify": {
                        "type": "string",
                        "description": "A javascript sentence that must evaluate to true. If it evaluates to false it means that the CDN was not reachable and the fallback resource will be loaded",
                        "examples": [
                            "window.jQuery"
                        ]
                    },
                    "fallbackResource": {
                        "type": "string",
                        "description": "The project path inside src/main from where the library fallback resource will be loaded if CDN is not available",
                        "examples": [
                            "libs/jquery/jquery.js"
                        ]
                    }
                }
            },
            "examples": [
                "TODO"
            ]
        },
        "globalJs": {
            "type": "array",
            "description": "List of js file paths (relative to src/main) that will be included globally on all the project views. All the specified files will be merged into a single global js file to optimize performance. The merge order will be exactly the same as the one defined here",
            "items": {
                "type": "string",
                "examples": [
                    "libs/turbocommons-es5/turbocommons-es5.js"
                ]
            }
        },
        "globalCss": {
            "type": "array",
            "description": "List of css file paths that will be included globally on all the project views. All the specified files will be merged into a single global css file to optimize performance. The merge order will be exactly the same as the one defined here",
            "items": {
                "type": "string",
                "description": "The Items Schema"
            },
            "examples": [
                "libs/normalize/normalize.css",
                "view/css/global-styles.scss",
                "view/components/main-menu/main-menu.scss",
                "view/components/footer/footer.scss"
            ]
        },
        "globalComponents": {
            "type": "array",
            "description": "A list of components that will be globally loaded right after the globalJs and globalCss. Each array element is a string with the path to a component (based on src/main) without a file extension",
            "items": {
                "type": "string",
                "description": "A path to the component (based on src/main) without the file extension"
            },
            "examples": [
                "view/components/main-menu/main-menu",
                "view/components/footer/footer"
            ]
        },
        "globalHtml": {
            "type": "object",
            "description": "Defines extra fragments of html that will be added globally to all the project views",
            "required": [
                "afterBodyOpen",
                "beforeBodyClose"
            ],
            "additionalProperties": false,
            "properties": {
                "afterBodyOpen": {
                    "type": "array",
                    "description": "List of paths to files containing html code that will be added just after the <body> tag on all the project views, sorted in the same order as here",
                    "items": {
                        "type": "string",
                        "description": "Path to a file containing some html code"
                    },
                    "examples": [
                        "view/components/google-analytics/google-analytics.html"
                    ]
                },
                "beforeBodyClose": {
                    "type": "array",
                    "description": "List of paths to files containing html code that will be added just before the </body> tag on all the project views, sorted in the same order as here",
                    "items": {
                        "type": "string",
                        "description": "Path to a file containing some html code"
                    },
                    "examples": [
                        "view/components/google-analytics/google-analytics.html"
                    ]
                }
            }
        },
        "viewComponents": {
            "type": "array",
            "description": "A list of components that will be loaded with specific views. They will be loaded after the global css, js and global elements. Each array item is an object with two properties: view (the name of the view that will load the component) and components (a list of paths based on src/main to the components to load with the view, without file extension)",
            "items": {
                "type": "object",
                "required": [
                    "view",
                    "components"
                ],
                "additionalProperties": false,
                "properties": {
                    "view": {
                        "type": "string",
                        "description": "A view name",
                        "examples": [
                            "home"
                        ]
                    },
                    "components": {
                        "type": "array",
                        "description": "A list of paths to the components based on src/main, without file extension",
                        "examples": [
                            "view/components/main-menu/main-menu"
                        ]
                    }
                }
            }
        },
        "webServices": {
            "type": "object",
            "description": "Defines the setup related to the web services exposed by the site at sitedomain.com/api",
            "required": [
                "crossOriginCORS",
                "api"
            ],
            "additionalProperties": false,
            "properties": {
                "crossOriginCORS": {
                    "type": "string",
                    "description": "Defines the Cross Origin Resource Sharing policy that applies to all the web services. restrict means only same domain is allowed, and allow means access is granted from anywhere",
                    "enum": [
                        "restrict",
                        "allow"
                    ]
                },
                "api": {
                    "type": "array",
                    "description": "List of API definitions. Each element links a URL services path to the code namespace where the respective webservice classes can be found",
                    "items": {
                        "type": "object",
                        "required": [
                            "uri",
                            "namespace"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "uri": {
                                "type": "string",
                                "description": "A fragment of the URL that calls the services which defines the services API path. Must start with api/ and no ending slash must exist",
                                "examples": [
                                    "api/site"
                                ]
                            },
                            "namespace": {
                                "type": "string",
                                "description": "The namespace where the webservice classes that relate to the specified URI can be found. Namespace must point to the root of the service classes folder that matches the specified URI fragment. No ending slash must exist",
                                "examples": [
                                    "project/src/main/api/site"
                                ]
                            }
                        }
                    }
                }
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "additionalProperties": false,
    "definitions": {
        "absolute_path": {
            "description": "A path only. Query string and/or fragment are not allowed.",
            "pattern": "^/(([a-zA-Z0-9._~!$&'()*+,;=:@-]|%[0-9a-fA-F]{2})+(/([a-zA-Z0-9._~!$&'()*+,;=:@-]|%[0-9a-fA-F]{2})*)*)?$",
            "type": "string"
        },
        "analytics_identifier": {
            "anyOf": [
                {
                    "type": "string"
                },
                {
                    "type": "null"
                }
            ],
            "description": "A short identifier we send to Google Analytics for multi-valued fields. This means we avoid the truncated values we would get if we sent the path or slug of eg organisations."
        },
        "change_history": {
            "items": {
                "additionalProperties": false,
                "properties": {
                    "note": {
                        "description": "A summary of the change",
                        "type": "string"
                    },
                    "public_timestamp": {
                        "_format": "date-time",
                        "type": "string"
                    }
                },
                "required": [
                    "public_timestamp",
                    "note"
                ],
                "type": "object"
            },
            "type": "array"
        },
        "details": {
            "additionalProperties": false,
            "properties": {
                "alternative_path": {
                    "format": "uri",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "change_history": {
                    "$ref": "#/definitions/change_history"
                },
                "explanation": {
                    "type": [
                        "string",
                        "null"
                    ]
                }
            },
            "type": "object"
        },
        "first_published_at": {
            "_format": "date-time",
            "description": "The date the content was first published.  Automatically determined by the publishing-api, unless overridden by the publishing application.",
            "type": "string"
        },
        "frontend_links": {
            "items": {
                "additionalProperties": true,
                "properties": {
                    "analytics_identifier": {
                        "$ref": "#/definitions/analytics_identifier"
                    },
                    "api_path": {
                        "$ref": "#/definitions/absolute_path"
                    },
                    "api_url": {
                        "_format": "uri",
                        "description": "DEPRECATED: api_path should be used instead of api_url. This is due to values of api_url being tied to an environment which can cause problems when data is synced between environments. In time this field will be removed by the Publishing Platform team.",
                        "type": "string"
                    },
                    "base_path": {
                        "$ref": "#/definitions/absolute_path"
                    },
                    "content_id": {
                        "$ref": "#/definitions/guid"
                    },
                    "document_type": {
                        "type": "string"
                    },
                    "links": {
                        "patternProperties": {
                            "^[a-z_]+$": {
                                "$ref": "#/definitions/frontend_links"
                            }
                        },
                        "type": "object"
                    },
                    "locale": {
                        "$ref": "#/definitions/locale"
                    },
                    "public_updated_at": {
                        "oneOf": [
                            {
                                "$ref": "#/definitions/public_updated_at"
                            },
                            {
                                "type": "null"
                            }
                        ]
                    },
                    "schema_name": {
                        "type": "string"
                    },
                    "title": {
                        "type": "string"
                    },
                    "web_url": {
                        "_format": "uri",
                        "description": "DEPRECATED: base_path should be used instead of web_url. This is due to values of web_url being tied to an environment which can cause problems when data is synced between environments. In time this field will be removed by the Publishing Platform team.",
                        "type": "string"
                    }
                },
                "required": [
                    "content_id",
                    "locale",
                    "title"
                ],
                "type": "object"
            },
