                },
                "default_popup": {
                    "$ref": "#/definitions/uri",
                    "description": "The popup appears when the user clicks the icon."
                },
                "default_icon": {
                    "anyOf": [
                        {
                            "type": "string",
                            "description": "FIXME: String form is deprecated."
                        },
                        {
                            "type": "object",
                            "description": "Icon for the main toolbar.",
                            "properties": {
                                "19": {
                                    "$ref": "#/definitions/icon"
                                },
                                "38": {
                                    "$ref": "#/definitions/icon"
                                }
                            }
                        }
                    ]
