            "default": "script-src 'self'; object-src 'self'"
        },
        "glob_pattern": {
            "type": "string",
            "format": "glob-pattern"
        },
        "icon": {
            "$ref": "#/definitions/uri"
        },
        "match_pattern": {
            "type": "string",
            "format": "match-pattern",
            "pattern": "^((\\*|http|https|file|ftp|chrome-extension):\\/\\/(\\*|\\*\\.[^\\/\\*]+|[^\\/\\*]+)?(\\/.*))|<all_urls>$"
        },
        "mime_type": {
            "type": "string",
            "format": "mime-type",
            "pattern": "^(?:application|audio|image|message|model|multipart|text|video)\\/[-+.\\w]+$"
        },
        "page": {
            "$ref": "#/definitions/uri"
        },
        "permissions": {
            "type": "array",
            "_uniqueItems": true,
            "items": {
                "type": "string",
                "format": "permission"
            }
        },
        "scripts": {
            "type": "array",
            "minItems": 1,
            "_uniqueItems": true,
            "items": {
                "$ref": "#/definitions/uri"
            }
        },
        "uri": {
            "type": "string"
        },
        "version_string": {
            "type": "string",
            "pattern": "^(?:\\d{1,5}\\.){0,3}\\d{1,5}$"
        }
    }
