                    "required": [
                        "name",
                        "type",
                        "proxied",
                        "create",
                        "zoneName"
                    ]
                }
            ]
        },
        "ipJsonEcho": {
            "type": "object",
            "description": "IP echo service that response with JSON.",
            "properties": {
