                                    "delegated",
                                    "consistent",
                                    "default",
                                    "ro"
                                ],
                                "type": "string"
                            },
                            "type": {
                                "description": "Type of volume mount",
                                "enum": [
                                    "local"
                                ],
                                "type": "string"
                            }
                        },
                        "required": [
                            "local",
                            "container"
                        ],
                        "type": "object"
                    },
                    {
                        "additionalProperties": false,
                        "properties": {
                            "container": {
                                "description": "Path inside the container to mount the cache at",
                                "minLength": 1,
                                "type": "string"
                            },
                            "name": {
                                "description": "Name of the cache",
                                "minLength": 1,
                                "type": "string"
                            },
                            "options": {
                                "description": "Docker volume mount options to use when creating mount",
                                "enum": [
                                    "cached",
                                    "delegated",
                                    "consistent",
                                    "default",
                                    "ro"
                                ],
                                "type": "string"
                            },
                            "type": {
                                "description": "Type of volume mount",
                                "enum": [
                                    "cache"
                                ],
                                "type": "string"
                            }
                        },
                        "required": [
                            "type",
                            "name",
                            "container"
                        ],
                        "type": "object"
                    }
                ]
            },
            "type": "array"
        }
    },
    "patternProperties": {
        "^\\.": {}
    },
    "properties": {
        "config_variables": {
            "$ref": "#/definitions/configVariablesList"
        },
        "containers": {
            "$ref": "#/definitions/containers"
        },
        "include": {
            "$ref": "#/definitions/includesList"
        },
        "project_name": {
            "description": "The name of your project. Used to label any images built.",
            "minLength": 1,
            "type": "string"
        },
        "tasks": {
            "$ref": "#/definitions/tasks"
        }
    },
    "title": "JSON schema for batect configuration files",
    "type": "object"
}

