                        "type": "string"
                    },
                    "project_group": {
                        "type": "string"
                    },
                    "module": {
                        "type": "string"
                    },
                    "branches": {
                        "type": "array",
                        "items": {
                            "type": "string"
                        }
                    },
                    "releases": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "tag_from": {
                                    "type": "string"
                                },
                                "tag_to": {
                                    "type": "string"
                                },
                                "release_name": {
                                    "type": "string"
