{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "additionalProperties": false,
    "definitions": {
        "contributor": {
            "additionalProperties": false,
            "description": "A contributor to a story (creator or editor).",
            "properties": {
                "contributorId": {
                    "description": "Unique identifier.",
                    "type": "string"
                },
                "email": {
                    "_format": "email",
                    "type": "string"
                },
                "itemRole": {
                    "description": "Contribution in relation to this piece of content.",
                    "type": "string"
                },
                "name": {
                    "description": "First and last name, as it appears in the byline.",
                    "type": "string"
                },
                "role": {
                    "description": "Creator's position at the news organization.",
                    "type": "string"
                }
            },
            "type": "object"
        },
        "location": {
            "additionalProperties": false,
            "description": "The location of the content.",
            "properties": {
                "city": {
                    "type": "string"
                },
                "country": {
                    "type": "string"
                },
                "latitude": {
                    "type": "number"
                },
                "longitude": {
                    "type": "number"
                },
                "state": {
                    "type": "string"
                }
            },
            "type": "object"
        },
        "mediaObject": {
            "additionalProperties": false,
            "description": "A generic container for a media object.",
            "properties": {
                "caption": {
                    "type": "string"
                },
                "creators": {
                    "items": {
                        "$ref": "#/definitions/contributor"
                    },
                    "type": "array"
                },
                "location": {
                    "$ref": "#/definitions/location"
                },
                "url": {
                    "type": "string"
                }
            },
            "type": "object"
        }
    },
    "description": "A story to be pushed to the Washington Post's WebSked planning tool.",
    "properties": {
        "analytics": {
            "additionalProperties": false,
            "description": "Contains various analytics information about the story.",
            "properties": {
                "comments": {
                    "description": "Number of comments the story has received.",
                    "type": "integer"
                },
                "pageViews": {
                    "type": "integer"
                },
                "shares": {
                    "description": "The number of times the story has been shared on various social media networks.",
                    "properties": {
                        "facebook": {
                            "type": "integer"
                        },
                        "googlePlus": {
                            "type": "integer"
                        },
                        "twitter": {
                            "type": "integer"
                        }
                    },
                    "type": "object"
                }
            },
            "type": "object"
        },
        "cms": {
            "description": "The name of the CMS from which the story originated.",
            "type": "string"
        },
        "cmsEditURL": {
            "_format": "uri",
            "description": "URL to open the story for editing in the CMS' web client.",
            "type": "string"
        },
        "contentType": {
            "description": "Content type of the story (eg, article, video, gallery).",
            "enum": [
                "article",
                "video",
                "gallery",
                "graphic",
                "image"
            ]
        },
        "creators": {
            "description": "Various information about the creators and contributors to a story.",
            "items": {
                "$ref": "#/definitions/contributor"
            },
            "type": "array"
        },
        "custom": {
            "description": "Organizations can use fields within custom to track data that is not captured in the WebSked data specification, but is relevant to their needs.",
            "properties": {},
            "type": "object"
        },
        "dates": {
            "additionalProperties": false,
            "description": "Various RFC3339-formatted datetimes associated with the story.",
            "properties": {
                "created": {
                    "_format": "date-time",
                    "description": "The RFC3339-formatted datetime at which the story was created in the CMS.",
                    "type": "string"
                },
                "planned": {
                    "description": "The RFC3339-formatted datetime at which the reporter expects the story to be ready, or null if this is still unknown. This is only an estimate and can be modified later.",
                    "_format": "date-time",
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "published": {
                    "_format": "date-time",
                    "description": "The RFC3339-formatted datetime at which the story was published on the web.",
                    "type": "string"
                },
                "scheduled": {
                    "_format": "date-time",
                    "description": "The RFC3339-formatted datetime at which the story will go live, if one has been determined.",
                    "type": "string"
                },
                "updated": {
                    "_format": "date-time",
                    "description": "The RFC3339-formatted datetime at which the story was last updated in the CMS.",
                    "type": "string"
                }
            },
            "required": [
                "created",
                "updated",
                "planned"
            ],
            "type": "object"
        },
        "editors": {
            "description": "Array containing information about each of the story's editors.",
            "items": {
                "$ref": "#/definitions/contributor"
            },
            "type": "array"
        },
        "headline": {
            "type": "string"
        },
        "html": {
            "description": "The actual content of the story, in HTML format.",
            "type": "string"
        },
        "id": {
            "description": "Immutable ID created in the CMS.",
            "type": "string"
        },
        "location": {
            "$ref": "#/definitions/location"
        },
        "media": {
            "additionalProperties": false,
            "description": "Contains information about the various media associated with the story.",
            "properties": {
                "galleries": {
                    "description": "An array of the galleries associated with this story.",
                    "items": {
                        "$ref": "#/definitions/mediaObject"
                    },
                    "type": "array"
                },
                "graphics": {
                    "description": "An array of the graphics associated with this story.",
                    "items": {
                        "$ref": "#/definitions/mediaObject"
                    },
                    "type": "array"
                },
                "images": {
                    "description": "An array of the images associated with this story.",
                    "items": {
                        "$ref": "#/definitions/mediaObject"
                    },
                    "type": "array"
                },
                "videos": {
                    "description": "An array of the videos associated with this story.",
                    "items": {
                        "$ref": "#/definitions/mediaObject"
                    },
                    "type": "array"
                },
                "willHaveGalleries": {
                    "description": "Whether or not the reporter anticipates that the story will have galleries.",
                    "type": "boolean"
                },
                "willHaveGraphics": {
                    "description": "Whether or not the reporter anticipates that the story will have graphics.",
                    "type": "boolean"
                },
                "willHaveImages": {
                    "description": "Whether or not the reporter anticipates that the story will have images.",
                    "type": "boolean"
                },
                "willHaveVideos": {
                    "description": "Whether or not the reporter anticipates that the story will have videos.",
                    "type": "boolean"
                }
            },
            "type": "object"
        },
        "originatingPlan": {
            "description": "The plan path from which the story originated.",
            "type": "string"
        },
        "plans": {
            "description": "An array of plan paths to which the story belongs.",
            "items": {
                "type": "string"
            },
            "type": "array"
        },
        "slug": {
            "description": "A short string by which to easily identify the story.",
            "type": "string"
        },
        "source": {
            "description": "The source of the content.",
            "type": "string"
        },
        "status": {
            "additionalProperties": false,
            "description": "Contains information about the current status of the story.",
            "properties": {
                "live": {
                    "description": "Whether or not the story is live on the web.",
                    "type": "boolean"
                },
                "publish": {
                    "description": "Denotes which of a number of organization-defined publish statuses the story is currently in.",
                    "type": "integer"
                },
                "publishRaw": {
                    "description": "The raw publish status from the CMS.",
                    "type": "string"
                },
                "workflow": {
                    "description": "Denotes which of a number of organization-defined workflow statuses the story is currently in.",
                    "type": "integer"
                },
                "workflowRaw": {
                    "description": "The raw workflow status from the CMS.",
                    "type": "string"
                }
            },
            "required": [
                "publish",
                "workflow",
                "live"
            ],
            "type": "object"
        },
        "storyLength": {
            "additionalProperties": false,
            "properties": {
                "actual": {
                    "description": "Current number of words.",
                    "type": "integer"
                },
                "planned": {
                    "description": "The anticipated number of words in the story.",
                    "type": "integer"
                }
            },
            "type": "object"
        },
        "summary": {
            "description": "A short summary of the story to be displayed in WebSked.",
            "type": "string"
        },
        "url": {
            "_format": "uri",
            "description": "Web URL for published stories.",
            "type": "string"
        },
        "usage": {
            "description": "Contains information about where and when the story has been used.",
            "items": {
                "additionalProperties": false,
                "properties": {
                    "endTime": {
                        "description": "Epoch time when the story was removed from this location.",
                        "type": "integer"
                    },
                    "locationId": {
                        "description": "Unique number for the location.",
                        "type": "integer"
                    },
                    "locationName": {
                        "description": "Human-readable location.",
                        "type": "string"
                    },
                    "startTime": {
                        "description": "Epoch time when the story went live at this location.",
                        "type": "integer"
                    }
                },
                "type": "object"
            },
            "type": "array"
        }
    },
    "required": [
        "id",
        "status",
        "contentType",
        "dates",
        "plans",
        "originatingPlan",
        "creators",
        "html",
        "headline"
    ],
    "title": "WebSked Story",
    "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "the shipment id that can be used for requesting info about a shipment or tracking it"
    },
    "carrier_tracking_no": {
      "type": "string",
      "description": "the original tracking number that can be used on the carriers website"
    },
    "carrier": {
      "type": "string",
      "enum": [
        "dhl",
        "ups",
        "dpd",
        "hermes",
        "gls"
      ],
      "description": "acronym of the carrier"
    },
    "created_at": {
      "type": "string",
      "description": "timestamp the shipment was created"
    },
    "tracking_url": {
      "type": "string",
      "description": "URL you can send your customers so they can track this shipment"
    },
    "label_url": {
      "type": "string",
      "description": "URL where you can download the label in pdf format"
    },
    "from": {
      "$ref": "#/definitions/address",
      "description": "If missing, the default sender address (if defined in your shipcloud account) will be used"
    },
    "to": {
      "$ref": "#/definitions/address",
      "description": "the receivers address"
    },
    "packages": {
      "type": "array",
      "items": {
        "allOf": [
          {
            "$ref": "#/definitions/package"
          }
        ],
        "properties": {
          "id": {
            "type": "string",
            "description": "identifier for a single package"
          },
          "tracking_events": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "timestamp": {
                  "type": "number",
                  "description": "timestamp of when this event occured"
                },
                "location": {
                  "type": "string",
                  "description": "location of the package at this moment"
                },
                "status": {
                  "type": "string",
                  "enum": [
                    "shipcloud_label_created",
                    "label_created",
                    "picked_up",
                    "delivered",
                    "not_delivered",
                    "transit",
                    "exception",
                    "out_for_delivery",
                    "unknown",
                    "canceled"
                  ],
                  "description": "key describing the status"
                },
                "details": {
                  "type": "string",
                  "description": "message the carrier sends to describe the package status"
                }
              },
              "required": [
                "timestamp",
                "location",
                "status",
                "details"
              ],
              "additionalProperties": false
            }
          }
        },
        "required": [
          "id"
        ],
        "additionalProperties": false
      }
    },
    "price": {
      "type": "number",
      "description": "price that we're going to charge you (exl. VAT)"
    },
    "reference_number": {
      "type": "string",
      "description": "a reference number (max. 30 characters) that you want this shipment to be identified with. You can use this afterwards to easier find the shipment in the shipcloud.io backoffice"
    }
  },
  "required": [
    "id",
    "carrier_tracking_no",
    "carrier",
    "created_at",
    "tracking_url",
    "label_url",
    "from",
    "to",
    "packages",
    "price",
    "reference_number"
  ],
  "additionalProperties": false,
  "definitions": {
    "address": {
      "type": "object",
      "properties": {
        "company": {
          "type": "string"
        },
        "first_name": {
          "type": "string"
        },
        "last_name": {
          "type": "string"
        },
        "care_of": {
          "type": "string"
        },
        "street": {
          "type": "string"
        },
        "street_no": {
          "type": "string"
        },
        "city": {
          "type": "string"
        },
        "zip_code": {
          "type": "string"
        },
        "country": {
          "type": "string",
          "description": "Country as uppercase ISO 3166-1 alpha-2 code"
        },
        "phone": {
          "type": "string"
        }
      },
      "required": [
        "last_name",
        "street",
        "street_no",
        "city",
        "zip_code",
        "country"
      ],
      "additionalProperties": false
    },
    "package": {
      "type": "object",
      "properties": {
        "width": {
          "type": "number"
        },
        "height": {
          "type": "number"
        },
        "length": {
          "type": "number"
        },
        "weight": {
          "type": "number"
        }
      },
      "required": [
        "width",
        "height",
        "length",
        "weight"
      ],
      "additionalProperties": false,
      "description": "defines package dimensions"
    }
  }
}

