                        },
                        "z": {
                            "$ref": "#/definitions/positiveNumber",
                            "description": "z location of center-bottom of well in reference to left-front-bottom of labware"
                        }
                    },
                    "required": [
                        "depth",
                        "shape",
                        "totalLiquidVolume",
                        "x",
                        "y",
                        "z"
                    ],
                    "type": "object"
                }
            },
            "type": "object"
        }
    },
    "required": [
