                                        "maxProperties": 1
                                    }
                                ]
                            },
                            "minItems": 1,
                            "_uniqueItems": true
                        },
                        "outs": {
                            "type": "array",
                            "description": "Outputs of the stage",
                            "items": {
                                "$ref": "#/definitions/Output"
                            },
                            "minItems": 1,
                            "_uniqueItems": true
                        },
                        "metrics": {
                            "type": "array",
                            "description": "Metrics outputs of the stage",
                            "items": {
                                "$ref": "#/definitions/Output"
                            },
                            "minItems": 1,
                            "_uniqueItems": true
