{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "OpenSCAD schema",
    "description": "Configuration for the OpenSCAD importer to import information for a step",
    "openscad": {
        "type": "object",
        "description": "A dictionary with openscad import data for different categories",
        "properties": {
            "images": {
                "type": "object",
                "description": "A dictionary for image imports",
                "patternProperties": {
                    "^([a-zA-Z][0-9a-zA-Z]*)$": {
                        "allOf": [
                            {
                                "$ref": "#/input"
                            },
                            {
                                "$ref": "#/image"
                            }
                        ]
                    }
                },
                "additionalProperties": false
            },
            "files": {
                "type": "object",
                "description": "A dictionary for file imports",
                "patternProperties": {
                    "^([a-zA-Z][0-9a-zA-Z]*)$": {
                        "allOf": [
                            {
                                "$ref": "#/input"
                            },
                            {
                                "$ref": "#/file"
                            }
                        ]
                    }
                },
                "additionalProperties": false
            },
            "parts": {
                "type": "object",
                "description": "A dictionary for part imports",
                "patternProperties": {
                    "^([a-zA-Z][0-9a-zA-Z]*)$": {
                        "allOf": [
                            {
                                "$ref": "#/input"
                            },
                            {
                                "$ref": "#/object"
                            }
                        ]
                    }
                },
                "additionalProperties": false
            },
            "tools": {
                "type": "object",
                "description": "A dictionary for tool imports",
                "patternProperties": {
                    "^([a-zA-Z][0-9a-zA-Z]*)$": {
                        "allOf": [
                            {
                                "$ref": "#/input"
                            },
                            {
                                "$ref": "#/object"
                            }
                        ]
                    }
                },
                "additionalProperties": false
            },
            "results": {
                "type": "object",
                "description": "A dictionary for result imports",
                "patternProperties": {
                    "^([a-zA-Z][0-9a-zA-Z]*)$": {
                        "allOf": [
                            {
                                "$ref": "#/input"
                            },
                            {
                                "$ref": "#/object"
                            }
                        ]
                    }
                },
                "additionalProperties": false
            }
        },
        "additionalProperties": false
    },
    "input": {
        "type": "object",
        "description": "The details of a module call, which yields an object when evaluated",
        "properties": {
            "scadfile": {
                "type": "string",
                "description": "The filename of the scad file"
            },
            "module": {
                "type": "string",
                "description": "Name of the module to be called, if omitted use full file"
            },
            "parameters": {
                "type": "array",
                "description": "Parameters to invoke module with"
            }
        },
        "required": [
            "scadfile"
        ]
    },
    "image": {
        "type": "object",
        "description": "Details about how the input should be transformed into a image",
        "properties": {
            "camera": {
                "type": "array",
                "description": "Position of the camera",
                "maxItems": 3,
                "minItems": 3,
                "items": {
                    "type": "number",
                    "description": "A coordinate"
                }
            },
            "size": {
                "type": "array",
                "description": "Size of the image",
                "maxItems": 2,
                "minItems": 2,
                "items": {
                    "type": "number",
                    "description": "A pixel number"
                }
            },
            "alt": {
                "type": "string",
                "description": "Textual description of the image"
            }
        }
    },
    "file": {
        "type": "object",
        "description": "Details about how the input should be transformed into a stl file",
        "properties": {
            "filename": {
                "type": "string",
                "description": "The filename of the exported stl"
            }
        },
        "required": [
            "filename"
        ]
    },
    "object": {
        "type": "object",
        "description": "Details about how the input should be transformed to an Object",
        "properties": {
            "name": {
                "type": "string",
                "description": "The name of the object"
            },
            "quantity": {
                "type": "number",
                "description": "Number of instances of this object",
                "default": 1
            },
            "optional": {
                "type": "boolean",
                "description": "If this object is strictly required",
                "default": false
            },
            "camera": {
                "type": "array",
                "description": "Position of the camera",
                "maxItems": 3,
                "minItems": 3,
                "items": {
                    "type": "number",
                    "description": "A coordinate"
                }
            },
            "size": {
                "type": "array",
                "description": "Size of the image",
                "maxItems": 2,
                "minItems": 2,
                "items": {
                    "type": "number",
                    "description": "A pixel number"
                }
            },
            "alt": {
                "type": "string",
                "description": "Textual description of the image"
            }
        },
        "required": [
            "name"
        ]
    },
    "properties": {
        "openscad": {
            "$ref": "#/openscad"
        },
        "input": {
            "$ref": "#/input"
        },
        "image": {
            "$ref": "#/image"
        },
        "file": {
            "$ref": "#/file"
        },
        "object": {
            "$ref": "#/object"
        }
    },
    "required": [
        "openscad",
        "input",
        "image",
        "file",
        "object"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "layout": {
            "type": "object",
            "description": "How to present the messages.",
            "properties": {
                "variant": {
                    "type": "integer",
                    "description": "A layout-variant code (preliminary; 1: no alert/border, 2: single alert, 3: one alert per error-class, 4: one alert per message).",
                    "default": 3
                }
            }
        },
        "dismiss": {
            "type": "object",
            "description": "Tells if and how messages may be dismissed by the user.",
            "properties": {
                "enabled": {
                    "type": "boolean",
                    "description": "If true, a button for dismissing is provided to the user.",
                    "default": true
                }
            }
        },
        "status": {
            "type": "object",
            "description": "Flags by which the most severe level among all messages is indicated.",
            "properties": {
                "ERROR": {
                    "type": "string",
                    "format": "topic",
                    "axRole": "outlet"
                },
                "WARNING": {
                    "type": "string",
                    "format": "topic",
                    "axRole": "outlet"
                },
                "INFO": {
                    "type": "string",
                    "format": "topic",
                    "axRole": "outlet"
                },
                "SUCCESS": {
                    "type": "string",
                    "format": "topic",
                    "axRole": "outlet"
                },
                "BLANK": {
                    "type": "string",
                    "format": "topic",
                    "axRole": "outlet"
                },
                "reset": {
                    "type": "object",
                    "description": "Delete all messages and set the state to BLANK",
                    "properties": {
                        "onActions": {
                            "type": "array",
                            "description": "List with actions",
                            "items": {
                                "type": "string",
                                "format": "topic",
                                "axRole": "inlet"
                            }
                        }
                    }
                }
            }
        },
        "errors": {
            "type": "object",
            "description": "If enabled, errors received via didEncounterError will be displayed too",
            "properties": {
                "enabled": {
                    "type": "boolean",
                    "default": true
                }
            }
        },
        "resource": {
            "type": "object",
            "description": "List of resources for which publish- and validation-messages are processed.",
            "properties": {
                "list": {
                    "type": [
                        "array",
                        "null"
                    ],
                    "description": "Resource topic list. Empty list serves as catch-all, null disables the resource-feature.",
                    "default": null,
                    "items": {
                        "type": "string",
                        "format": "topic",
                        "axRole": "inlet"
                    }
                },
                "exclude": {
                    "type": "array",
                    "description": "A list of resources to exclude from the display in case resource.list is set to catch-all.",
                    "items": {
                        "type": "string",
                        "format": "topic",
                        "axRole": "inlet"
                    }
                },
                "replace": {
                    "type": "boolean",
                    "description": "Whether to replace messages with success message.",
                    "default": false
                }
            }
        },
        "autoScroll": {
            "type": "object",
            "description": "Scroll the messages into the visible area of the window when receiving messages.",
            "properties": {
                "enabled": {
                    "type": "boolean",
                    "default": false,
                    "description": "If true the widget scrolls the messages into the visible area when receiving them."
                }
            }
        },
        "i18n": {
            "description": "Which locale to use for displaying this widget.",
            "type": "object",
            "properties": {
                "locale": {
                    "type": "string",
                    "format": "topic",
                    "axRole": "inlet",
                    "description": "The topic under which to expect the locale for this widget.",
                    "default": "default"
                }
            }
        }
    }
}

