                                    "null"
                                ]
                            }
                        }
                    }
                }
            },
            "if": {
                "properties": {
                    "stability": {
                        "const": "stable"
                    }
                }
            },
            "properties": {
                "body": {
                    "$ref": "#/definitions/Body"
                },
                "deprecated": {
                    "$ref": "#/definitions/Deprecated"
                },
                "documentation": {
                    "$ref": "#/definitions/Documentation"
                },
                "params": {
                    "$ref": "#/definitions/Params"
                },
