                                "additionalProperties": false,
                                "required": [
                                    "sequenceName",
                                    "position"
                                ]
                            }
                        }
                    },
                    "additionalProperties": false,
                    "required": [
                        "authorIdentity"
                    ]
                }
            },
            "required": [
                "id",
                "type",
                "version",
                "time"
            ],
            "additionalProperties": false
        },
        "data": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "BUG",
                        "IMPROVEMENT",
                        "FEATURE",
                        "WORK_ITEM",
                        "REQUIREMENT",
                        "OTHER"
                    ]
                },
                "tracker": {
                    "type": "string"
                },
                "id": {
                    "type": "string"
                },
                "uri": {
                    "type": "string"
                },
                "title": {
                    "type": "string"
                },
                "customData": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "key": {
                                "type": "string"
                            },
                            "value": {}
                        },
                        "required": [
                            "key",
                            "value"
                        ],
                        "additionalProperties": false
                    }
                }
            },
            "required": [
                "type",
                "tracker",
                "id",
                "uri"
            ],
            "additionalProperties": false
        },
        "links": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "type": {
                        "type": "string"
                    },
                    "target": {
                        "type": "string",
                        "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"
                    }
                },
                "required": [
                    "type",
                    "target"
                ],
                "additionalProperties": false
            }
        }
    }
