{
    "title": "FxA Push Payload schema",
    "description": "This schema defines what is acceptable to send as a payload data with the Push API from the FxA servers to a device connected to FxA",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "anyOf": [
        {
            "$ref": "#/definitions/deviceConnected"
        },
        {
            "$ref": "#/definitions/deviceDisconnected"
        },
        {
            "$ref": "#/definitions/profileUpdated"
        },
        {
            "$ref": "#/definitions/collectionsChanged"
        },
        {
            "$ref": "#/definitions/passwordChanged"
        },
        {
            "$ref": "#/definitions/passwordReset"
        },
        {
            "$ref": "#/definitions/accountDestroyed"
        },
        {
            "$ref": "#/definitions/commandReceived"
        }
    ],
    "definitions": {
        "deviceConnected": {
            "required": [
                "version",
                "command",
                "data"
            ],
            "properties": {
                "version": {
                    "type": "integer",
                    "description": "The version of this push payload data instance. Bump this if you make changes to any part of this schema."
                },
                "command": {
                    "type": "string",
                    "description": "Helps the receiving device discriminate payloads",
                    "enum": [
                        "fxaccounts:device_connected"
                    ]
                },
                "data": {
                    "type": "object",
                    "required": [
                        "deviceName"
                    ],
                    "properties": {
                        "deviceName": {
                            "type": "string",
                            "description": "The name of the device who joined this account"
                        }
                    },
                    "additionalProperties": false
                }
            },
            "additionalProperties": false
        },
        "deviceDisconnected": {
            "required": [
                "version",
                "command",
                "data"
            ],
            "properties": {
                "version": {
                    "type": "integer"
                },
                "command": {
                    "type": "string",
                    "enum": [
                        "fxaccounts:device_disconnected"
                    ]
                },
                "data": {
                    "type": "object",
                    "required": [
                        "id"
                    ],
                    "properties": {
                        "id": {
                            "type": "string",
                            "description": "The id of the device who was disconnected remotely"
                        }
                    },
                    "additionalProperties": false
                }
            },
            "additionalProperties": false
        },
        "profileUpdated": {
            "required": [
                "version",
                "command"
            ],
            "properties": {
                "version": {
                    "type": "integer"
                },
                "command": {
                    "type": "string",
                    "enum": [
                        "fxaccounts:profile_updated"
                    ]
                }
            },
            "additionalProperties": false
        },
        "collectionsChanged": {
            "required": [
                "version",
                "command",
                "data"
            ],
            "properties": {
                "version": {
                    "type": "integer"
                },
                "command": {
                    "type": "string",
                    "enum": [
                        "sync:collection_changed"
                    ]
                },
                "data": {
                    "type": "object",
                    "required": [
                        "collections"
                    ],
                    "properties": {
                        "collections": {
                            "type": "array",
                            "minItems": 1,
                            "_uniqueItems": true,
                            "description": "A list of collections that were changed",
                            "items": {
                                "enum": [
                                    "addons",
                                    "bookmarks",
                                    "history",
                                    "forms",
                                    "prefs",
                                    "tabs",
                                    "passwords",
                                    "clients"
                                ]
                            }
                        },
                        "reason": {
                            "type": "string",
                            "enum": [
                                "sendtab",
                                "firstsync"
                            ],
                            "description": "Event that lead to this push notification"
                        }
                    },
                    "additionalProperties": false
                }
            },
            "additionalProperties": false
        },
        "passwordChanged": {
            "required": [
                "version",
                "command"
            ],
            "properties": {
                "version": {
                    "type": "integer"
                },
                "command": {
                    "type": "string",
                    "enum": [
                        "fxaccounts:password_changed"
                    ]
                }
            },
            "additionalProperties": false
        },
        "passwordReset": {
            "required": [
                "version",
                "command"
            ],
            "properties": {
                "version": {
                    "type": "integer"
                },
                "command": {
                    "type": "string",
                    "enum": [
                        "fxaccounts:password_reset"
                    ]
                }
            },
            "additionalProperties": false
        },
        "accountDestroyed": {
            "required": [
                "version",
                "command",
                "data"
            ],
            "properties": {
                "version": {
                    "type": "integer"
                },
                "command": {
                    "type": "string",
                    "enum": [
                        "fxaccounts:account_destroyed"
                    ]
                },
                "data": {
                    "type": "object",
                    "required": [
                        "uid"
                    ],
                    "properties": {
                        "uid": {
                            "type": "string",
                            "description": "The UID of the account which was destroyed"
                        }
                    },
                    "additionalProperties": false
                }
            },
            "additionalProperties": false
        },
        "commandReceived": {
            "required": [
                "version",
                "command",
                "data"
            ],
            "properties": {
                "version": {
                    "type": "integer"
                },
                "command": {
                    "type": "string",
                    "enum": [
                        "fxaccounts:command_received"
                    ]
                },
                "data": {
                    "type": "object",
                    "required": [
                        "command",
                        "index",
                        "url"
                    ],
                    "properties": {
                        "command": {
                            "type": "string",
                            "description": "URI identifying the command that was invoked"
                        },
                        "index": {
                            "type": "integer",
                            "description": "index of this command in the device's command queue"
                        },
                        "sender": {
                            "type": "string",
                            "description": "The device ID from which the command was sent, if known"
                        },
                        "url": {
                            "type": "string",
                            "description": "URL at which to fetch the full command payload"
                        }
                    },
                    "additionalProperties": false
                }
            },
            "additionalProperties": false
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "$id": "https://raw.githubusercontent.com/OpenLightingProject/open-fixture-library/master/schemas/definitions.json",
    "$comment": "This file is used by another schema file and should not be used directly as a JSON schema.",
    "nonEmptyString": {
        "type": "string",
        "pattern": "^[^\n]+$"
    },
    "noVariablesString": {
        "type": "string",
        "pattern": "^[^$\n]+$"
    },
    "variablePixelKeyString": {
        "type": "string",
        "pattern": "\\$pixelKey"
    },
    "nonEmptyMultilineString": {
        "type": "string",
        "minLength": 1
    },
    "modeNameString": {
        "allOf": [
            {
                "$ref": "#/nonEmptyString"
            },
            {
                "pattern": "^((?!mode)(?!Mode).)*$"
            }
        ]
    },
    "urlString": {
        "type": "string",
        "pattern": "^(ftp|http|https)://[^ \"]+$",
        "format": "uri"
    },
    "urlArray": {
        "type": "array",
        "minItems": 1,
        "_uniqueItems": true,
        "items": {
            "$ref": "#/urlString"
        }
    },
    "isoDateString": {
        "type": "string",
        "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$",
        "format": "date"
    },
    "colorString": {
        "type": "string",
        "pattern": "^#[0-9a-f]{6}$",
        "format": "color-hex"
    },
    "dimensionsXYZ": {
        "$comment": "width, height, depth (in mm)",
        "type": "array",
        "minItems": 3,
        "maxItems": 3,
        "items": {
            "type": "number",
            "minimum": 0
        }
    },
    "effectPreset": {
        "enum": [
            "ColorJump",
            "ColorFade"
        ]
    },
    "goboResourceString": {
        "type": "string",
        "oneOf": [
            {
                "pattern": "^gobos/[a-z0-9-]+$"
            },
            {
                "pattern": "^gobos/aliases/[a-z0-9_.-]+/"
            }
        ]
    },
    "units": {
        "number": {
            "type": "number"
        },
        "nonNegativeNumber": {
            "type": "number",
            "minimum": 0
        },
        "positiveInteger": {
            "type": "integer",
            "minimum": 0,
            "exclusiveMinimum": 0
        },
        "dmxValue": {
            "type": "integer",
            "minimum": 0,
            "$comment": "maximum depends on how many fine channels there are (255 if none, 65535 if one, etc.)"
        },
        "dmxValuePercent": {
            "type": "string",
            "pattern": "^(([1-9][0-9]?|0)(\\.[0-9]+)?|100)%$"
        },
        "percent": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?%$"
        },
        "hertz": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?Hz$"
        },
        "beatsPerMinute": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?bpm$"
        },
        "roundsPerMinute": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?rpm$"
        },
        "seconds": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?s$"
        },
        "milliSeconds": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?ms$"
        },
        "meters": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?m$"
        },
        "lumens": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?lm$"
        },
        "kelvin": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?K$"
        },
        "volumePerMinute": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?m\\^3/min$"
        },
        "degrees": {
            "type": "string",
            "pattern": "^-?[0-9]+(\\.[0-9]+)?deg$"
        }
    },
    "entities": {
        "speed": {
            "oneOf": [
                {
                    "$ref": "#/units/hertz"
                },
                {
                    "$ref": "#/units/beatsPerMinute"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "fast",
                        "slow",
                        "stop",
                        "slow reverse",
                        "fast reverse"
                    ]
                }
            ]
        },
        "rotationSpeed": {
            "oneOf": [
                {
                    "$ref": "#/units/hertz"
                },
                {
                    "$ref": "#/units/roundsPerMinute"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "fast CW",
                        "slow CW",
                        "stop",
                        "slow CCW",
                        "fast CCW"
                    ]
                }
            ]
        },
        "time": {
            "oneOf": [
                {
                    "$ref": "#/units/seconds"
                },
                {
                    "$ref": "#/units/milliSeconds"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "instant",
                        "short",
                        "long"
                    ]
                }
            ]
        },
        "distance": {
            "oneOf": [
                {
                    "$ref": "#/units/meters"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "near",
                        "far"
                    ]
                }
            ]
        },
        "brightness": {
            "oneOf": [
                {
                    "$ref": "#/units/lumens"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "off",
                        "dark",
                        "bright"
                    ]
                }
            ]
        },
        "colorTemperature": {
            "oneOf": [
                {
                    "$ref": "#/units/kelvin"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "warm",
                        "CTO",
                        "default",
                        "cold",
                        "CTB"
                    ]
                }
            ]
        },
        "fogOutput": {
            "oneOf": [
                {
                    "$ref": "#/units/volumePerMinute"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "off",
                        "weak",
                        "strong"
                    ]
                }
            ]
        },
        "rotationAngle": {
            "oneOf": [
                {
                    "$ref": "#/units/degrees"
                },
                {
                    "$ref": "#/units/percent"
                }
            ]
        },
        "beamAngle": {
            "oneOf": [
                {
                    "$ref": "#/units/degrees"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "closed",
                        "narrow",
                        "wide"
                    ]
                }
            ]
        },
        "horizontalAngle": {
            "oneOf": [
                {
                    "$ref": "#/units/degrees"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "left",
                        "center",
                        "right"
                    ]
                }
            ]
        },
        "verticalAngle": {
            "oneOf": [
                {
                    "$ref": "#/units/degrees"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "top",
                        "center",
                        "bottom"
                    ]
                }
            ]
        },
        "swingAngle": {
            "oneOf": [
                {
                    "$ref": "#/units/degrees"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "closed",
                        "narrow",
                        "wide"
                    ]
                }
            ]
        },
        "parameter": {
            "oneOf": [
                {
                    "$ref": "#/units/number"
                },
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "off",
                        "low",
                        "high",
                        "slow",
                        "fast",
                        "small",
                        "big",
                        "instant",
                        "short",
                        "long"
                    ]
                }
            ]
        },
        "slotNumber": {
            "$ref": "#/units/nonNegativeNumber"
        },
        "percent": {
            "oneOf": [
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "off",
                        "low",
                        "high"
                    ]
                }
            ]
        },
        "insertion": {
            "oneOf": [
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "out",
                        "in"
                    ]
                }
            ]
        },
        "irisPercent": {
            "oneOf": [
                {
                    "$ref": "#/units/percent"
                },
                {
                    "enum": [
                        "closed",
                        "open"
                    ]
                }
            ]
        }
    },
    "properties": {
        "nonEmptyString": {
            "$ref": "#/nonEmptyString"
        },
        "noVariablesString": {
            "$ref": "#/noVariablesString"
        },
        "variablePixelKeyString": {
