    "properties": {
        "numero": {
            "type": "string"
        },
        "chaveAcesso": {
            "type": "string"
        },
        "codigoModelo": {
            "type": "string"
        },
        "dataInicioVigenciaModelo": {
            "type": "string"
        },
        "orgao": {
            "type": "string"
        },
        "situacao": {
            "type": "object",
            "properties": {
                "id": {
                    "type": "string"
                },
                "descricao": {
                    "type": "string"
                }
            }
        },
        "dataSituacaoAtual": {
            "type": "string"
        },
        "importadorExportador": {
            "type": "string"
        },
        "declarante": {
            "type": [
                "string",
                "null"
            ]
        },
        "prorrogacaoPendente": {
            "type": "boolean"
        },
        "retificacaoPendente": {
            "type": "boolean"
        },
        "unidadeMedidaEstatistica": {
            "type": [
                "string",
                "null"
            ]
        },
        "unidadeMedidaComercializada": {
            "type": [
                "string",
                "null"
            ]
        },
        "informacaoAdicional": {
            "type": [
                "string",
                "null"
            ]
        },
        "listaNcm": {
            "type": "array",
