        "logical_axioms": {
            "items": {
                "$ref": "#/definitions/printf_owl"
            },
            "type": "array"
        },
        "name": {
            "$ref": "#/definitions/printf_annotation_obo",
            "mapping": "rdfs:label"
        },
        "namespace": {
            "$ref": "#/definitions/printf_annotation_obo",
            "mapping": "oboInOwl:hasOBONamespace"
        },
        "narrow_synonym": {
            "$ref": "#/definitions/list_annotation_obo",
            "mapping": "oboInOwl:hasNarrowSynonym"
        },
        "objectProperties": {
            "description": "A dictionary of OWL object properties. key : label; value : short form id",
            "type": "object"
        },
        "pattern_name": {
            "description": "The name of the pattern.  This must be an ASCII string with no spaces. The only special characters allowed are '_' and '-'. By convention, this is used as the file name of the pattern - with an appropriate extension.\n",
            "type": "string"
        },
        "readable_identifiers": {
            "description": "A list of annotation properties used as naming fields, in order of preference.",
            "items": {
                "type": "string"
            },
            "type": "array"
        },
        "related_synonym": {
            "$ref": "#/definitions/list_annotation_obo",
            "mapping": "oboInOwl:hasRelatedSynonym"
        },
        "relations": {
            "description": "A dictionary of OWL object properties. key : label; value : short form id",
            "type": "object"
        },
        "subClassOf": {
            "$ref": "#/definitions/printf_owl_convenience"
        },
        "substitutions": {
            "items": {
                "$ref": "#/definitions/regex_sub"
            },
            "type": "array"
        },
        "vars": {
            "description": "A dictionary of variables ranging over OWL classes.   Key = variable name, value = variable range as manchester syntax string.\n",
            "type": "object"
        },
        "xref": {
            "$ref": "#/definitions/list_annotation_obo",
            "mapping": "oboInOwl:hasDbXref"
        }
    },
    "title": "DOSDP",
    "type": "object"
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "definitions": {
        "FileMetadata": {
            "type": "object",
            "title": "File Metadata",
            "properties": {
                "identifiers": {
                    "type": "object",
                    "title": "Namespace Identifiers",
                    "description": "Sandbox for file ID information (e.g. echonest ID, musicbrainz ID, etc.)."
                },
                "artist": {
                    "type": "string"
                },
                "title": {
                    "type": "string"
                },
                "release": {
                    "type": "string"
                },
                "duration": {
                    "type": "number",
                    "minimum": 0.0
                },
                "jams_version": {
                    "type": "string",
                    "pattern": "[0-9].[0-9].[0-9]"
                }
            }
        },
        "Curator": {
            "type": "object",
            "title": "Curator",
            "description": "Curator contact information: name and email",
            "properties": {
                "name": {
                    "type": "string"
                },
                "email": {
                    "type": "string",
                    "format": "email"
                }
            },
            "required": [
                "name",
                "email"
            ]
        },
        "AnnotationMetadata": {
            "type": "object",
            "title": "Annotation metadata",
            "description": "All metadata required to describe an annotation",
            "properties": {
                "corpus": {
                    "type": "string"
                },
                "version": {
                    "type": [
                        "string",
                        "number"
                    ]
                },
                "curator": {
                    "$ref": "#/definitions/Curator"
                },
                "annotator": {
                    "type": "object",
                    "title": "Annotator",
                    "description": "Sandbox for information about the annotator."
                },
                "annotation_tools": {
                    "type": "string"
                },
                "annotation_rules": {
                    "type": "string"
                },
                "validation": {
                    "type": "string"
                },
                "data_source": {
                    "type": "string"
                }
            }
        },
        "SparseObservation": {
            "type": "object",
            "title": "SparseObservation",
            "description": "An observation that spans an interval of time",
            "properties": {
                "value": {},
                "confidence": {},
                "time": {
                    "type": "number",
                    "minimum": 0.0
                },
                "duration": {
                    "type": "number",
                    "minimum": 0.0
                }
            },
            "required": [
                "value",
                "time",
                "duration",
                "confidence"
            ]
        },
        "DenseObservation": {
            "type": "object",
            "title": "DenseObservation",
            "description": "A dense series of observations",
            "properties": {
                "value": {
                    "type": "array"
                },
                "confidence": {
                    "type": "array"
                },
                "time": {
                    "type": "array",
                    "items": {
                        "type": "number",
                        "minimum": 0.0
                    }
                },
                "duration": {
                    "type": "array",
                    "items": {
                        "type": "number",
                        "minimum": 0.0
                    }
                }
            },
            "required": [
                "value",
                "time",
                "duration",
                "confidence"
            ]
        },
        "SparseObservationList": {
            "type": "array",
            "title": "Sparse Observation List",
            "id": "#sparse-observation-list",
            "description": "A list of sparse observation objects",
            "items": {
                "$ref": "#/definitions/SparseObservation"
            }
        },
        "Annotation": {
            "id": "#annotation",
            "type": "object",
            "title": "Annotation",
            "description": "An annotation of a single observation, e.g. tags",
            "properties": {
                "annotation_metadata": {
                    "$ref": "#/definitions/AnnotationMetadata"
                },
                "data": {
                    "title": "Data",
                    "description": "An array of observations",
                    "oneOf": [
                        {
                            "$ref": "#/definitions/DenseObservation"
                        },
                        {
                            "$ref": "#/definitions/SparseObservationList"
                        }
                    ]
                },
                "namespace": {
                    "type": "string"
                },
                "sandbox": {
                    "type": "object"
                },
                "time": {
                    "oneOf": [
                        {
                            "type": "number",
                            "minimum": 0.0
                        },
                        {
                            "type": "null"
                        }
                    ]
                },
                "duration": {
                    "oneOf": [
                        {
                            "type": "number",
                            "minimum": 0.0
                        },
                        {
                            "type": "null"
                        }
                    ]
                }
            },
            "required": [
                "annotation_metadata",
                "data",
                "namespace"
            ]
        }
    },
    "type": "object",
    "title": "JAMS file",
    "description": "JSON Annotated Music Specification",
    "properties": {
        "file_metadata": {
            "$ref": "#/definitions/FileMetadata"
        },
        "annotations": {
            "type": "array",
            "title": "Annotations",
            "description": "Array of annotations",
            "items": {
                "$ref": "#/definitions/Annotation"
            }
        },
        "sandbox": {
            "type": "object"
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "scipm child -*- coding: utf-8 -*-",
    "type": "object",
    "additionalProperties": false,
    "properties": {
        "version": {
            "enum": [
                "1"
            ],
            "description": "scipm child package"
        },
        "scipmDependencies": {
            "type": "object",
            "additionalProperties": false,
            "patternProperties": {
                "^[a-zA-Z0-9](.*)$": {
                    "type": [
                        "null"
                    ]
                }
            }
        },
        "luaRequire": {
            "type": "array",
            "description": "example : IF ``mime`` THEN scipm build add code ``mime = require \"mime\";`` at top of SciTEStartup.lua (once)",
            "minItems": 0,
            "items": {
                "type": "string",
                "pattern": "^(.*)$",
                "minLength": 1
            }
        },
        "SciTEStartup": {
            "type": "object",
            "description": "exec lua command in SciTEStartup.lua",
            "additionalProperties": false,
            "properties": {
                "_use": {
                    "enum": [
                        "no",
                        "raw",
                        "dofile",
                        "filePath"
                    ],
                    "description": "exec lua in node raw or in node filePath. or dofile (else no)"
                },
                "raw": {
                    "type": [
                        "null",
                        "string"
                    ],
                    "description": "raw lua code",
                    "minLength": 1
                },
                "filePath": {
                    "type": [
                        "null",
                        "string"
                    ],
                    "description": "lua file to include",
                    "minLength": 1
                },
                "dofile": {
                    "type": [
                        "array"
                    ],
                    "description": "dofile path (items join by scipm scipm.data.path.sep)",
                    "minItems": 0,
                    "items": {
                        "type": "string",
                        "pattern": "^(.*)$",
                        "minLength": 1
                    }
                },
                "luaReportExtend": {
                    "type": [
                        "null",
                        "string"
                    ],
                    "description": "lua to add in package ``scipmHiddenDoString=`` report line",
                    "minLength": 1
                },
                "infoLuaFunctions": {
                    "type": "array",
                    "description": "list functions allowed by this package",
                    "items": {
                        "type": "object",
                        "description": "function info",
                        "additionalProperties": false,
                        "properties": {
                            "name": {
                                "type": "string",
                                "description": "function name",
                                "minLength": 1
                            }
                        },
                        "required": [
                            "name"
                        ]
                    }
                },
                "infoProps": {
                    "type": "array",
                    "description": "list props allowed by this package",
                    "items": {
                        "type": "object",
                        "description": "props info",
                        "additionalProperties": false,
                        "properties": {
                            "name": {
                                "type": "string",
                                "description": "props name",
                                "minLength": 1
                            },
                            "value": {
                                "type": "string",
                                "description": "props value allowed",
                                "minLength": 1
                            },
                            "default": {
                                "type": "string",
                                "description": "props default value",
                                "minLength": 1
                            },
                            "description": {
                                "type": "string",
                                "description": "props description",
                                "minLength": 1
                            }
                        },
                        "required": [
                            "name",
                            "value",
                            "default",
                            "description"
                        ]
                    }
                },
                "infoFiles": {
                    "type": "array",
                    "description": "list files by this package",
                    "items": {
                        "type": "object",
                        "description": "function info",
                        "additionalProperties": false,
                        "properties": {
                            "path": {
                                "type": "array",
                                "description": "items join by scipm scipm.data.path.sep",
                                "minItems": 1,
                                "items": {
                                    "type": "string",
                                    "pattern": "^(.*)$",
                                    "minLength": 1
                                }
                            }
                        },
                        "required": [
                            "path"
                        ]
                    }
                }
            },
            "required": [
                "_use",
                "raw",
                "filePath",
                "luaReportExtend",
                "infoLuaFunctions",
                "infoFiles",
                "infoProps"
            ]
        },
        "actions": {
            "type": "object",
            "description": "action to add in menu/context menu...",
            "additionalProperties": false,
            "patternProperties": {
                "^[a-zA-Z0-9](.*)$": {
                    "type": "object",
                    "additionalProperties": true,
                    "properties": {
                        "title": {
                            "type": "string",
                            "description": "default title in tool and context menu",
                            "minLength": 1
                        },
                        "description": {
                            "type": "string",
                            "description": "default description",
                            "minLength": 1
                        },
                        "pattern": {
                            "type": "array",
                            "minItems": 1,
                            "items": {
                                "type": "string",
                                "pattern": "^(.*)$",
                                "minLength": 1
                            }
                        },
                        "addToolsMenu": {
                            "type": "object",
                            "description": "add action in scite tool menu (switch pattern)",
                            "additionalProperties": false,
                            "properties": {
                                "allow": {
                                    "type": "boolean",
                                    "default": true
                                },
                                "addContextMenu": {
                                    "type": "boolean",
                                    "description": "action in context menu depend of action in tool menu (need command number)",
                                    "default": false
                                },
                                "command": {
                                    "type": "object",
                                    "description": "SciTE command subsystem",
                                    "additionalProperties": false,
                                    "properties": {
                                        "subsystem": {
                                            "type": "string",
                                            "enum": [
                                                "console",
                                                "windows",
                                                "shellexec",
                                                "luadirector",
                                                "htmlhelp",
                                                "winhelp",
                                                "immediate"
                                            ],
                                            "description": "see http://www.scintilla.org/SciTEDoc.html :: Command subsystem",
                                            "default": "console"
                                        },
                                        "shortcuts": {
                                            "type": [
                                                "null",
                                                "string"
                                            ],
                                            "description": "default shortcut. Null = no shortcut",
                                            "minLength": 1
                                        },
                                        "isFilter": {
                                            "type": [
                                                "null",
                                                "string"
                                            ],
                                            "enum": [
                                                null,
                                                "0",
                                                "1"
                                            ],
                                            "description": "The optional command.is.filter property states that the command modifies the current file so it may need to be read in after performing the command if load.on.activate is set.",
                                            "default": "null"
                                        },
                                        "saveBefore": {
                                            "type": [
                                                "null",
                                                "string"
                                            ],
                                            "enum": [
                                                null,
                                                "1",
                                                "2"
                                            ],
                                            "description": "If command.save.before is set to 1, SciTE automatically saves the file before execution. If it is set to 2, SciTE will not save the file, otherwise SciTE asks you",
                                            "default": "null"
                                        },
                                        "input": {
                                            "type": [
                                                "null",
                                                "string"
                                            ],
                                            "description": "On Windows, the optional command.input property specifies text that will be piped to the command. This may reference other properties; for example, command.input.0.*.cc=$(CurrentSelection) would pipe the current selection to the command processes. The command.input property is only supported for subsystem 0 (command line programs).",
                                            "default": "null"
                                        },
                                        "mode": {
                                            "type": [
                                                "null",
                                                "string"
                                            ],
                                            "description": "The command.mode property is a comma-separated list of flags / settings. Each mode setting can have an argument, separated from the setting name by a colon. For most of these, the argument portion is optional; if the setting name appears without an argument, this works the same as \"setting:yes\". If a setting is included in the command.mode but also appears as a separate command property, the mode property will be overridden. Similarly, if a single setting appears more than once with different arguments, the last valid argument takes priority. The supported command.mode settings are: filter - accepts keyword arguments yes and no, quiet - accepts keyword arguments yes and no, replaceselection - accepts yes, no, and auto, savebefore - accepts yes, no, and prompt, subsystem - console, windows, shellexec, lua, director, winhelp, htmlhelp, immediate, groupundo - yes or no, Currently, all of these except groupundo are based on individual properties with similar names, and so are not described separately here. The groupundo setting works with subsystem 3 (lua / director), and indicates that SciTE should treat any changes made by the command as a single undo action. A command that uses the groupundo setting should not change which buffer is active in the editor.",
                                            "default": "null"
                                        },
                                        "quiet": {
                                            "type": [
                                                "null",
                                                "string"
                                            ],
                                            "enum": [
                                                null,
                                                "1"
                                            ],
                                            "description": "A final command property that is currently supported only on windows is command.quiet. A value of 1 indicates that the command I/O should not be echoed to the output pane. This may be useful in combination with command.input and command.replace.selection.",
                                            "default": "null"
                                        },
                                        "replaceSelection": {
                                            "type": [
                                                "null",
                                                "string"
                                            ],
                                            "enum": [
                                                null,
                                                "0",
                                                "1",
                                                "2"
                                            ],
                                            "description": "The optional command.replace.selection can be used to specify that the command output should replace the current selection (or be inserted at the cursor location, if there is no selection)",
                                            "default": "null"
                                        },
                                        "cmd": {
                                            "type": [
                                                "string"
                                            ],
                                            "description": "command to exec (switch selected subsystems).",
                                            "minLength": 1
                                        }
                                    },
                                    "required": [
                                        "subsystem",
                                        "cmd",
                                        "shortcuts",
                                        "isFilter",
                                        "saveBefore",
                                        "input",
                                        "replaceSelection",
                                        "quiet",
                                        "mode"
                                    ]
                                }
                            },
                            "required": [
                                "allow",
                                "addContextMenu",
                                "command"
                            ]
                        }
                    },
                    "required": [
                        "pattern",
                        "addToolsMenu",
                        "title",
                        "description"
                    ]
                }
            }
        }
    },
    "required": [
        "version",
        "scipmDependencies",
        "luaRequire",
        "SciTEStartup",
        "actions"
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "title": "Alarm Configuration",
    "description": "Lists alarms",
    "limited": false,
    "strictProps": false,
    "definitions": {
        "emailRecipient": {
            "title": "E-mail recipient",
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "title": "Type",
                    "enum": [
                        "email"
                    ],
                    "default": "email",
                    "options": {
                        "hidden": true
                    },
                    "propertyOrder": 1
                },
                "to": {
                    "type": "string",
                    "title": "E-mail address",
                    "minLength": 1,
                    "propertyOrder": 2
                },
                "subject": {
                    "type": "string",
                    "title": "Subject",
                    "description": "{} will be replaced with alarm message text",
                    "propertyOrder": 3
                }
            },
            "required": [
                "type",
                "to"
            ]
        },
        "smsRecipient": {
            "title": "SMS recipient",
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "title": "Type",
                    "enum": [
                        "sms"
                    ],
                    "default": "sms",
                    "options": {
                        "hidden": true
                    },
                    "propertyOrder": 1
                },
                "to": {
                    "type": "string",
                    "title": "Phone number",
                    "minLength": 1,
                    "propertyOrder": 2
                },
                "command": {
                    "type": "string",
                    "title": "Command",
                    "propertyOrder": 3
                }
            },
            "required": [
                "type",
                "to"
            ]
        },
        "alarmBase": {
            "type": "object",
            "properties": {
                "name": {
                    "type": "string",
                    "title": "Alarm name",
                    "minLength": 1,
                    "propertyOrder": 1
                },
                "cell": {
                    "type": "string",
                    "title": "Cell",
                    "description": "Use the following format: device/control",
                    "pattern": "^[^/+#]+/[^/+#]+$",
                    "minLength": 3,
                    "propertyOrder": 2
                },
                "alarmMessage": {
                    "type": "string",
                    "title": "Alarm activation message",
                    "description": "{} will be replaced by target cell value",
                    "propertyOrder": 3
                },
                "noAlarmMessage": {
                    "type": "string",
                    "title": "Alarm deactivation message",
                    "description": "{} will be replaced by target cell value",
                    "propertyOrder": 4
                },
                "interval": {
                    "type": "integer",
                    "title": "Alarm interval in seconds",
                    "description": "If specified, alarm messages will be repeated while the alarm is active",
                    "propertyOrder": 5
                },
                "maxCount": {
                    "type": "integer",
                    "title": "Maximum number of messages",
                    "description": "Maximum number of messages to send while the alarm is active",
                    "propertyOrder": 6
                },
                "alarmDelayMs": {
                    "type": "integer",
                    "title": "Alarm Activation Delay",
                    "description": "If set, the alarm condition must be violated for the specified time interval (in ms) for the alarm to be triggered",
                    "minimum": 0,
                    "default": 0,
                    "propertyOrder": 7
                },
                "noAlarmDelayMs": {
                    "type": "integer",
                    "title": "Alarm Deactivation Delay",
                    "description": "If set, the alarm condition must be met for the specified time interval (in ms) for the alarm to be cleared",
                    "minimum": 0,
                    "default": 0,
                    "propertyOrder": 8
                }
            }
        },
        "minValue": {
            "type": "number",
            "title": "Minimum value",
            "description": "Alarm activates when cell value is less than the minimum value"
        },
        "maxValue": {
            "type": "number",
            "title": "Maximum value",
            "description": "Alarm activates when cell value is greater than the maximum value"
        },
        "expectedValueAlarm": {
            "title": "Expected Value Alarm",
            "defaultProperties": [
                "name",
                "cell",
                "alarmMessage",
                "noAlarmMessage",
                "alarmDelayMs",
                "expectedValue"
            ],
            "allOf": [
                {
                    "$ref": "#/definitions/alarmBase"
                },
                {
                    "properties": {
                        "expectedValue": {
                            "title": "Expected value",
                            "description": "Alarm activates when cell value differs from the expected value"
                        }
                    },
                    "required": [
                        "name",
                        "cell",
                        "expectedValue"
                    ]
                }
            ]
        },
        "minValueAlarm": {
            "title": "Minimum Value Alarm",
            "defaultProperties": [
                "name",
                "cell",
                "alarmMessage",
                "noAlarmMessage",
                "alarmDelayMs",
                "minValue"
            ],
            "allOf": [
                {
                    "$ref": "#/definitions/alarmBase"
                },
                {
                    "properties": {
                        "minValue": {
                            "$ref": "#/definitions/minValue",
                            "propertyOrder": 10
                        }
                    },
                    "required": [
                        "name",
                        "cell",
                        "minValue"
                    ]
                },
                {
                    "not": {
                        "required": [
                            "maxValue"
                        ]
                    }
                }
            ]
        },
        "maxValueAlarm": {
            "title": "Maximum Value Alarm",
            "defaultProperties": [
                "name",
                "cell",
                "alarmMessage",
                "noAlarmMessage",
                "alarmDelayMs",
                "maxValue"
            ],
            "allOf": [
                {
                    "$ref": "#/definitions/alarmBase"
                },
                {
                    "properties": {
                        "maxValue": {
                            "$ref": "#/definitions/maxValue",
                            "propertyOrder": 10
                        }
                    },
                    "required": [
                        "name",
                        "cell",
                        "maxValue"
                    ]
                },
                {
                    "not": {
                        "required": [
                            "minValue"
                        ]
                    }
                }
            ]
        },
        "minMaxValueAlarm": {
            "title": "Minimum&Maximum Value Alarm",
            "defaultProperties": [
                "name",
                "cell",
                "alarmMessage",
                "noAlarmMessage",
                "minValue",
                "maxValue"
            ],
            "allOf": [
                {
                    "$ref": "#/definitions/alarmBase"
                },
                {
                    "properties": {
                        "minValue": {
                            "$ref": "#/definitions/minValue",
                            "propertyOrder": 10
                        },
                        "maxValue": {
                            "$ref": "#/definitions/maxValue",
                            "propertyOrder": 11
                        }
                    },
                    "required": [
                        "name",
                        "cell",
                        "minValue",
                        "maxValue"
                    ]
                }
            ]
        },
        "recipient": {
            "options": {
                "disable_collapse": true
            },
            "title": "Recipient",
            "oneOf": [
                {
                    "$ref": "#/definitions/emailRecipient"
                },
                {
                    "$ref": "#/definitions/smsRecipient"
                }
            ]
        },
        "alarm": {
            "headerTemplate": "Alarm{{: |self.name}}",
            "oneOf": [
                {
                    "$ref": "#/definitions/expectedValueAlarm"
                },
                {
