                    "$ref": "#/definitions/github_issue&prs_with_time_duration"
                },
                "month": {
                    "$ref": "#/definitions/github_issue&prs_with_time_duration"
                }
            },
            "additionalProperties": false
        },
        "github_last_year_commits_details": {
            "type": "object",
