{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "JSON schema for component.json files",
    "type": "object",
    "additionalProperties": true,
    "properties": {
        "private": {
            "description": "A boolean specifying whether the component is private, defaulting to  false.",
            "type": "boolean",
            "default": false
        },
        "name": {
            "description": "A public component MUST have a 'name'. This is what will be passed to  require().",
            "type": "string",
            "pattern": "^[0-9a-z-_]+$"
        },
        "repo": {
            "description": "The public component MUST have a 'repository' property, this is registry end-point consisting of  <username>/<project> , for example 'visionmedia/page.js' or 'component/dialog'.",
            "type": "string"
        },
        "description": {
            "description": "The component SHOULD have a 'description' property. This helps people find and understand your component.",
            "type": "string"
        },
        "version": {
            "description": "The public component MUST include a version, allowing other scripts to depend on specific releases of the component.",
            "type": "string"
        },
        "keywords": {
            "description": "Keywords are used when searching for a component. A public component SHOULD list a few keywords.",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "main": {
            "description": "It is recommended that you use 'index.js' for the main component file, however if you use another filename, you MUST define a 'main' field for that.",
            "type": "string"
        },
        "scripts": {
            "description": "The  scripts  field explicitly specifies the scripts for this component. For public components, these must be regular JavaScript files. For private components, these should be regular Javascript files.",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "styles": {
            "description": "The  styles  field explicitly specifies the stylesheets for this component. For public components, these must be regular CSS files. For private components, these should be regular CSS files.",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "json": {
            "description": "The  json  field explicitly specifies the  JSON  files for this component. Each file must be valid  JSON .",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "images": {
            "description": "The  images  field MUST be supported and fetched upon installation, this allows component build tools to rewrite stylesheet  url() s in order to accomodate various file serving techniques.",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "fonts": {
            "description": "The  fonts  field MUST be supported and fetched upon installation, this allows component build tools to rewrite stylesheet  url() s in order to accomodate various file serving techniques.",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "files": {
            "description": "In the future we will classify more file types, however for those which are not treated uniquely such as fonts may be placed in a  files  array to aid build and installation tools.",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "dependencies": {
            "description": "Runtime dependencies.",
            "type": "object",
            "additionalProperties": {
                "type": "string"
            }
        },
        "locals": {
            "description": "Local dependencies are already located on disk, these are not installed, but are however included in the builds, thus no versions need to be defined. Local components should be located in a directory specified within .paths.",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "remotes": {
            "description": "The public component must not contain any remotes.",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "paths": {
            "description": "The public component must not contain any paths.",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "templates": {
            "description": "The templates array MUST provide the contents of each file as a require-able module. For example the following must provide the HTML string via require('user.html').",
            "type": "array",
            "items": {
                "type": "string",
                "minItems": 1
            }
        },
        "demo": {
            "type": "string"
        },
        "development": {
            "$ref": "#"
        },
        "license": {
            "description": "The license string such as 'MIT' may be used for search output and other reporting, developers SHOULD specify this field",
            "type": "string"
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "id": "https://mkvtoolnix.download/doc/mkvmerge-identification-output-schema-v10.json",
    "title": "mkvmerge identification output",
    "description": "The JSON output produced by mkvmerge's file identification mode",
    "additionalProperties": false,
    "type": "object",
    "properties": {
        "attachments": {
            "description": "an array describing the attachments found if any",
            "type": "array",
            "items": {
                "additionalProperties": false,
                "type": "object",
                "properties": {
                    "content_type": {
                        "type": "string",
                        "minLength": 1
                    },
                    "description": {
                        "type": "string"
                    },
                    "file_name": {
                        "type": "string"
                    },
                    "id": {
                        "type": "integer",
                        "minimum": 0
                    },
                    "size": {
                        "type": "integer",
                        "minimum": 0
                    },
                    "properties": {
                        "additionalProperties": false,
                        "type": "object",
                        "properties": {
                            "uid": {
                                "type": "integer",
                                "minimum": 0
                            }
                        }
                    },
                    "type": {
                        "type": "string"
                    }
                },
                "required": [
                    "file_name",
                    "id",
                    "properties",
                    "size"
                ]
            }
        },
        "chapters": {
            "type": "array",
            "items": {
                "additionalProperties": false,
                "type": "object",
                "properties": {
                    "num_entries": {
                        "type": "integer"
                    }
                },
                "required": [
                    "num_entries"
                ]
            }
        },
        "container": {
            "additionalProperties": false,
            "description": "information about the identified container",
            "type": "object",
            "properties": {
                "properties": {
                    "additionalProperties": false,
                    "description": "additional properties for the container varying by container format",
                    "type": "object",
                    "properties": {
                        "container_type": {
                            "description": "A unique number identifying the container type that's supposed to stay constant over all future releases of MKVToolNix",
                            "type": "integer",
                            "minLength": 1
                        },
                        "date_local": {
                            "description": "The muxing date in ISO 8601 format (in local time zone)",
                            "type": "string",
                            "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([+-][0-9]{2}:[0-9]{2}|Z)$"
                        },
                        "date_utc": {
                            "description": "The muxing date in ISO 8601 format (in UTC)",
                            "type": "string",
                            "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([+-][0-9]{2}:[0-9]{2}|Z)$"
                        },
                        "duration": {
                            "description": "The file's/segment's duration in nanoseconds",
                            "type": "integer",
                            "minimum": 0
                        },
                        "is_providing_timestamps": {
                            "description": "States whether or not the container has timestamps for the packets (e.g. Matroska, MP4) or not (e.g. SRT, MP3)",
                            "type": "boolean"
                        },
                        "muxing_application": {
                            "description": "A Unicode string containing the name and possibly version of the low-level library or application that created the file",
                            "type": "string"
                        },
                        "next_segment_uid": {
                            "description": "A hexadecimal string of the next segment's UID (only for Matroska files)",
                            "type": "string",
                            "minLength": 32,
                            "maxLength": 32
                        },
                        "other_file": {
                            "description": "An array of names of additional files processed as well",
                            "type": "array",
                            "items": {
                                "type": "string"
                            }
                        },
                        "playlist": {
                            "description": "States whether or not the identified file is a playlist (e.g. MPLS) referring to several other files",
                            "type": "boolean"
                        },
                        "playlist_chapters": {
                            "description": "The number of chapters in a playlist if it is a one",
                            "type": "integer",
                            "minimum": 0
                        },
                        "playlist_duration": {
                            "description": "The total duration in nanoseconds of all files referenced by the playlist if it is a one",
                            "type": "integer",
                            "minimum": 0
                        },
                        "playlist_file": {
                            "description": "An array of file names the playlist contains",
                            "type": "array",
                            "items": {
                                "type": "string"
                            }
                        },
                        "playlist_size": {
                            "description": "The total size in bytes of all files referenced by the playlist if it is a one",
                            "type": "integer",
                            "minimum": 0
                        },
                        "previous_segment_uid": {
                            "description": "A hexadecimal string of the previous segment's UID (only for Matroska files)",
                            "type": "string",
                            "minLength": 32,
                            "maxLength": 32
                        },
                        "programs": {
                            "description": "A container describing multiple programs multiplexed into the source file, e.g. multiple programs in one DVB transport stream",
                            "type": "array",
                            "items": {
                                "additionalProperties": false,
                                "description": "Properties describing a single program",
                                "type": "object",
                                "properties": {
                                    "program_number": {
                                        "description": "A unique number identifying a set of tracks that belong together; used e.g. in DVB for multiplexing multiple stations within a single transport stream",
                                        "type": "integer",
