        },
        "terminationCost": {
            "type": "boolean"
        },
        "termsAndConditionsDocument": {
            "type": "string"
        },
        "termsAndConditionsDocumentURL": {
            "_format": "uri",
            "type": "string"
        },
        "title": {
            "type": "string"
        },
        "vatIncluded": {
            "type": "boolean"
