    "required": [
        "id",
        "supplierId",
        "lot",
        "title",
        "serviceTypes",
        "serviceName",
        "serviceSummary",
        "serviceBenefits",
        "serviceFeatures",
        "serviceDefinitionDocument",
        "serviceDefinitionDocumentURL",
        "termsAndConditionsDocument",
        "termsAndConditionsDocumentURL",
        "minimumContractPeriod",
        "terminationCost",
        "priceMin",
        "priceUnit",
        "priceString",
        "vatIncluded",
