                                1200,
                                1800,
                                2400,
                                4800,
                                9600,
                                19200,
                                38400,
                                57600,
                                115200,
                                230400
                            ],
                            "default": 300,
                            "description": "Baudrate to be used to for initial communication with the meter."
                        },
                        "baudrate_read": {
                            "type": "integer",
                            "enum": [
                                50,
                                75,
                                110,
                                134,
