                                200,
                                300,
                                600,
                                1200,
                                1800,
                                2400,
                                4800,
                                9600,
                                19200,
                                38400,
                                57600,
                                115200,
                                230400
                            ],
                            "default": 300,
                            "description": "Baudrate to be used after initial handshake (pullseq/answer/ackseq). Has to fit to ackseq. Will be determined automatically if ackseq 'auto' is used."
                        },
                        "parity": {
                            "type": "string",
                            "enum": [
                                "8n1",
