        "credit_url": {
            "type": "string",
            "pattern": "^(https?:\\/\\/)?([\\da-z\\.-]+)\\.([a-z\\.]{2,6})([\\/\\w \\.-]*)*\\/?$",
            "description": "URL to be used to link to the teaser source.",
            "pbj": {
                "type": "text",
                "rule": "single",
                "format": "url"
            }
        },
        "gallery_ref": {
            "type": "string",
            "pattern": "^[\\w\\/\\.:-]+$",
            "pbj": {
                "type": "identifier",
                "rule": "single"
            }
        },
        "timeline_ref": {
            "type": "string",
            "pattern": "^[\\w\\/\\.:-]+$",
            "pbj": {
                "type": "identifier",
                "rule": "single"
            }
        },
        "youtube_video_id": {
            "type": "string",
            "pattern": "^[\\w-]+$",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        }
    },
    "required": [
        "_id",
        "youtube_video_id"
    ],
    "additionalProperties": true
