                                    "with_gene_id": {
                                        "type": "string"
                                    }
                                },
                                "required": [
                                    "creation_date",
                                    "publication",
                                    "type"
                                ],
                                "oneOf": [
                                    {
                                        "required": [
                                            "gene"
                                        ]
                                    },
                                    {
                                        "required": [
                                            "genotype"
                                        ]
                                    },
                                    {
                                        "required": [
                                            "metagenotype"
                                        ]
                                    }
                                ]
                            }
