{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "id": "https://sharphosting.uk/schemas/sites",
    "title": "Sites",
    "description": "Schema for data describing web server configurations.",
    "type": "object",
    "properties": {
        "web_server": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^[a-z]([a-z0-9_-]*[a-z])?$"
                },
                "user": {
                    "type": "string"
                },
                "group": {
                    "type": "string"
                }
            },
            "required": [
                "type",
                "user",
                "group"
            ],
            "additionalProperties": false
        },
        "directory_structure": {
            "type": "object",
            "properties": {
                "user": {
                    "type": "string"
                },
                "group": {
                    "type": "string"
                },
                "d_mode": {
                    "type": "string",
                    "pattern": "^[0-7]{3,4}$"
                },
                "f_mode": {
                    "type": "string",
                    "pattern": "^[0-7]{3,4}$"
                },
                "directories": {
                    "type": "object",
                    "patternProperties": {
                        "^[^/ ]+$": {
                            "title": "Directory",
                            "type": "object",
                            "properties": {
                                "allow_specials": {
                                    "type": "boolean"
                                },
                                "user": {
                                    "type": "string"
                                },
                                "group": {
                                    "type": "string"
                                },
                                "d_mode": {
                                    "type": "string",
                                    "pattern": "^[0-7]{3,4}$"
                                },
                                "f_mode": {
                                    "type": "string",
                                    "pattern": "^[0-7]{3,4}$"
                                },
                                "optional": {
                                    "type": "string",
                                    "pattern": "^[a-z]([a-z0-9_-]*[a-z])?$"
                                },
                                "optional_default": {
