        },
        "alias": {
            "type": "object",
            "properties": {
                "aliasOf": {
                    "description": "ID of the aliased reference. Note aliasing can be recursive.",
                    "$ref": "#/definitions/id"
                }
            },
            "required": [
                "aliasOf"
            ],
            "additionalProperties": false
        },
        "ref": {
            "type": "object",
            "properties": {
                "authors": {
                    "description": "Authors of the specification",
