{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "id": "https://mkvtoolnix.download/doc/mkvmerge-identification-output-schema-v7.json",
    "title": "mkvmerge identification output",
    "description": "The JSON output produced by mkvmerge's file identification mode",
    "additionalProperties": false,
    "type": "object",
    "properties": {
        "attachments": {
            "description": "an array describing the attachments found if any",
            "type": "array",
            "items": {
                "additionalProperties": false,
                "type": "object",
                "properties": {
                    "content_type": {
                        "type": "string",
                        "minLength": 1
                    },
                    "description": {
                        "type": "string"
                    },
                    "file_name": {
                        "type": "string"
                    },
                    "id": {
                        "type": "integer",
                        "minimum": 0
                    },
                    "size": {
                        "type": "integer",
                        "minimum": 0
                    },
                    "properties": {
                        "additionalProperties": false,
                        "type": "object",
                        "properties": {
                            "uid": {
                                "type": "integer",
                                "minimum": 0
                            }
                        }
                    },
                    "type": {
                        "type": "string"
                    }
                },
                "required": [
                    "file_name",
                    "id",
                    "properties",
                    "size"
                ]
            }
        },
        "chapters": {
            "type": "array",
            "items": {
                "additionalProperties": false,
                "type": "object",
                "properties": {
                    "num_entries": {
                        "type": "integer"
                    }
                },
                "required": [
                    "num_entries"
                ]
            }
        },
        "container": {
            "additionalProperties": false,
            "description": "information about the identified container",
