                            },
                            "codec_id": {
                                "type": "string"
                            },
                            "codec_private_data": {
                                "type": "string"
                            },
                            "codec_private_length": {
                                "type": "integer",
                                "minimum": 0
                            },
                            "content_encoding_algorithms": {
                                "type": "string",
                                "minLength": 1
                            },
                            "default_duration": {
                                "type": "integer",
                                "minimum": 0
                            },
                            "default_track": {
                                "type": "boolean"
                            },
                            "display_dimensions": {
                                "type": "string",
                                "pattern": "^[0-9]+x[0-9]+$"
