        "show_controls": {
            "type": "boolean",
            "default": true,
            "pbj": {
                "type": "boolean",
                "rule": "single"
            }
        },
        "show_position_indicators": {
            "type": "boolean",
            "default": true,
            "pbj": {
                "type": "boolean",
                "rule": "single"
            }
        }
    },
    "required": [
        "_id"
    ],
    "additionalProperties": true
}

