            "type": "object",
            "additionalProperties": false,
            "default": {},
            "properties": {
                "HaltOnSuspendResume": {
                    "type": "boolean",
                    "default": true
                },
                "RsynCheckPeriodInSeconds": {
                    "type": "number",
                    "default": 900
                },
                "DockerCheckPeriodInSeconds": {
                    "type": "number",
                    "default": 60
                }
            }
        },
        "images": {
            "title": "Your docker images",
            "type": "array",
            "items": {
                "$ref": "#/definitions/image"
            }
        },
        "hosts": {
            "type": "array",
            "items": {
                "type": "object"
            },
            "minItems": 1
        },
        "workspaces": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/workspace"
            }
        },
        "containers": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/container"
            }
        }
