                }
            ],
            "type": "object"
        }
    },
    "description": "This version of the Atom schema is based on version 1.0 of the format specifications, found here http://www.atomenabled.org/developers/syndication/atom-format-spec.php. The original namespace was http://www.w3.org/2005/Atom but we changed it to http://www.opengis.net/atom/2005 to avoid conflicting definitions of the same namespace in the future. NOT DONE YET. There is no XSD official schema for atom but this one seems to be the most known: http://www.kbcafe.com/rss/atom.xsd.xml (The Atom Publishing Protocol was issued as a Proposed Standard in IETF RFC 5023 in October 2007 http://tools.ietf.org/html/rfc5023)\nAn Atom document may have two root elements, feed and entry, as defined in section 2.",
    "properties": {
        "feed": {
            "$ref": "#/definitions/feedType"
        }
    },
    "required": [
        "feed"
    ],
    "title": "test/atomSchema.xsd",
    "type": "object"
}

{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "title": "JSON schema for elm.json configuration files",
    "definitions": {
        "exactDependency": {
            "description": "Dependencies are specified by [author name]/[package name]: [exact version].",
            "type": "object",
            "additionalProperties": {
                "type": "string"
            }
        },
        "rangeDependency": {
            "description": "Dependencies are specified by [author name]/[package name]: [exact version or range]. Range versions look like: [1.0.0 <= v < 2.0.0].",
            "type": "object",
            "additionalProperties": {
                "type": "string"
            }
        },
        "packageSpecificProperties": {
            "type": "object",
            "properties": {
                "name": {
                    "description": "The name of your package.",
                    "type": "string",
                    "minLength": 1
                },
                "license": {
                    "description": "An OSI approved license for your package.",
                    "type": "string",
                    "enum": [
                        "AFL-1.1",
                        "AFL-1.2",
                        "AFL-2.0",
                        "AFL-2.1",
                        "AFL-3.0",
                        "APL-1.0",
                        "Apache-1.1",
                        "Apache-2.0",
                        "APSL-1.0",
                        "APSL-1.1",
                        "APSL-1.2",
                        "APSL-2.0",
                        "Artistic-1.0",
                        "Artistic-1.0-Perl",
                        "Artistic-1.0-cl8",
                        "Artistic-2.0",
                        "AAL",
                        "BSL-1.0",
                        "BSD-2-Clause",
                        "BSD-3-Clause",
                        "0BSD",
                        "CECILL-2.1",
                        "CNRI-Python",
                        "CDDL-1.0",
                        "CPAL-1.0",
                        "CPL-1.0",
                        "CATOSL-1.1",
                        "CUA-OPL-1.0",
                        "EPL-1.0",
                        "ECL-1.0",
                        "ECL-2.0",
                        "EFL-1.0",
                        "EFL-2.0",
                        "Entessa",
                        "EUDatagrid",
                        "EUPL-1.1",
                        "Fair",
                        "Frameworx-1.0",
                        "AGPL-3.0",
                        "GPL-2.0",
                        "GPL-3.0",
                        "LGPL-2.1",
                        "LGPL-3.0",
                        "LGPL-2.0",
                        "HPND",
                        "IPL-1.0",
                        "Intel",
                        "IPA",
                        "ISC",
                        "LPPL-1.3c",
                        "LiLiQ-P-1.1",
                        "LiLiQ-Rplus-1.1",
                        "LiLiQ-R-1.1",
                        "LPL-1.02",
                        "LPL-1.0",
                        "MS-PL",
                        "MS-RL",
                        "MirOS",
                        "MIT",
                        "Motosoto",
                        "MPL-1.0",
                        "MPL-1.1",
                        "MPL-2.0",
                        "MPL-2.0-no-copyleft-exception",
                        "Multics",
                        "NASA-1.3",
                        "Naumen",
                        "NGPL",
                        "Nokia",
                        "NPOSL-3.0",
                        "NTP",
                        "OCLC-2.0",
                        "OGTSL",
                        "OSL-1.0",
                        "OSL-2.0",
                        "OSL-2.1",
                        "OSL-3.0",
                        "OSET-PL-2.1",
                        "PHP-3.0",
                        "PostgreSQL",
                        "Python-2.0",
                        "QPL-1.0",
                        "RPSL-1.0",
                        "RPL-1.1",
                        "RPL-1.5",
                        "RSCPL",
                        "OFL-1.1",
                        "SimPL-2.0",
                        "Sleepycat",
                        "SISSL",
                        "SPL-1.0",
                        "Watcom-1.0",
                        "UPL-1.0",
                        "NCSA",
                        "VSL-1.0",
                        "W3C",
                        "Xnet",
                        "Zlib",
                        "ZPL-2.0"
                    ]
                },
                "summary": {
                    "description": "A helpful summary of your package, less than 80 characters",
                    "type": "string",
                    "minLength": 1,
                    "maxLength": 79
                },
                "version": {
                    "description": "Your package's version in semantic versioning format.",
                    "type": "string",
                    "pattern": "\\d+\\.\\d+\\.\\d+"
                },
                "elm-version": {
                    "description": "The version of elm your package is targeting",
                    "type": "string"
                },
                "exposed-modules": {
                    "description": "All modules that your project will make available to end users.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "dependencies": {
                    "description": "A list of elm dependencies that your package needs for in production.",
                    "$ref": "#/definitions/rangeDependency"
                },
                "test-dependencies": {
                    "description": "A list of elm dependencies that your package uses only for testing.",
                    "$ref": "#/definitions/rangeDependency"
                }
            },
            "required": [
                "name",
                "license",
                "summary",
                "version",
                "elm-version",
                "exposed-modules",
                "dependencies",
                "test-dependencies"
            ]
        },
        "applicationSpecificProperties": {
            "type": "object",
            "properties": {
                "source-directories": {
                    "description": "A list of directories that will be used to build your project.",
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                },
                "elm-version": {
                    "description": "The version of elm your project is targeting",
                    "type": "string",
                    "pattern": "\\d+\\.\\d+\\.\\d+",
                    "enum": [
                        "0.19.0"
                    ]
                },
                "dependencies": {
                    "description": "A list of elm dependencies that your project needs for in production.",
                    "type": "object",
                    "properties": {
                        "direct": {
                            "$ref": "#/definitions/exactDependency"
                        },
                        "indirect": {
                            "$ref": "#/definitions/exactDependency"
                        }
                    },
                    "required": [
                        "direct",
                        "indirect"
                    ]
                },
                "test-dependencies": {
                    "description": "A list of elm dependencies that your project uses only for testing.",
                    "type": "object",
                    "properties": {
                        "direct": {
                            "$ref": "#/definitions/exactDependency"
                        },
                        "indirect": {
                            "$ref": "#/definitions/exactDependency"
                        }
                    },
                    "required": [
                        "direct",
                        "indirect"
                    ]
                }
            },
            "required": [
                "source-directories",
                "elm-version",
                "dependencies",
                "test-dependencies"
            ]
        }
    },
    "properties": {
        "type": {
            "description": "Specifies if your project will be a package or an application",
            "type": "string",
            "enum": [
                "application",
                "package"
            ]
        }
    },
    "if": {
        "properties": {
            "type": {
                "enum": [
                    "package"
                ]
            }
        }
    },
    "then": {
        "$ref": "#/definitions/packageSpecificProperties"
    },
    "else": {
        "if": {
            "properties": {
                "type": {
                    "enum": [
                        "application"
                    ]
                }
            }
        },
        "then": {
            "$ref": "#/definitions/applicationSpecificProperties"
        },
        "else": {}
    },
    "required": [
        "type"
    ]
}

{
    "_copyright": "Copyright (c) 2014 Juniper Networks, Inc. All rights reserved.",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "id": {
            "type": "string",
            "default": null,
            "description": "Id of the cluster being added. This is a mandatory parameter."
        },
        "email": {
            "type": "string",
            "default": null,
            "description": "Email id to send status of reimage/provision."
        },
        "base_image_id": {
            "type": "string",
            "default": null,
            "description": "Id of base image OS that the cluster will be reimaged with."
        },
        "package_image_id": {
            "type": "string",
            "default": null,
            "description": "Id of Contrail package that the cluster will be provisioned with."
        },
        "parameters": {
            "type": "object",
            "properties": {
                "domain": {
                    "type": "string",
                    "default": null,
                    "description": "Domain that all the servers of the cluster will default to."
                },
                "subnet_mask": {
                    "type": "string",
                    "pattern": "^$|^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])(/[0-9][0-9])?$",
                    "default": null,
                    "description": "Subnet mask that all the servers of the cluster will default to."
                },
                "gateway": {
                    "type": "string",
                    "pattern": "^$|^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])(/[0-9][0-9])?$",
                    "default": null,
                    "description": "Gateway IP that all the servers of the cluster will default to."
                },
                "password": {
                    "type": "string",
                    "default": null,
                    "description": "Root Password that all the servers of the cluster will default to."
                },
                "provision": {
                    "type": "object",
                    "properties": {
                        "contrail": {
                            "type": "object",
                            "properties": {
                                "xmpp_auth_enable": {
                                    "type": "boolean",
                                    "default": false,
                                    "description": "flag to indicate if xmpp athentication is enabled between control node and vrouter agent."
                                },
                                "xmpp_dns_auth_enable": {
                                    "type": "boolean",
                                    "default": false,
                                    "description": "flag to indicate if xmpp athentication is enabled between control node and vrouter dns agent."
                                },
                                "kernel_upgrade": {
                                    "type": "boolean",
                                    "default": true,
                                    "description": "Whether to upgrade kernel version of target servers."
                                },
                                "kernel_version": {
                                    "type": "string",
                                    "default": "",
                                    "description": "Kernel version to upgrade to. Optional parameter. Default upgrades to kernel version included with contrail package, if upgrade flag is set."
                                },
                                "enable_lbass": {
                                    "type": "boolean",
                                    "default": false,
                                    "description": "flag to indicate if lbaas feature is enabled for the cluster."
                                },
                                "amqp_ssl": {
                                    "type": "boolean",
                                    "default": false,
                                    "description": "Flag to enable or disable rabbitmq server SSL support globally for openstack and contrail config"
                                },
                                "ha": {
                                    "type": "object",
                                    "properties": {
                                        "haproxy_enable": {
                                            "type": "boolean",
                                            "default": true,
                                            "description": "Whether HAproxy service is enabled or disabled."
                                        },
                                        "contrail_internal_vip": {
                                            "type": "string",
                                            "pattern": "^$|^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])(/[0-9][0-9])?$",
                                            "default": "",
                                            "description": "Virtual Interface IP to be used for control/data interface of contrail HA nodes"
                                        },
                                        "contrail_external_vip": {
                                            "type": "string",
                                            "pattern": "^$|^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])(/[0-9][0-9])?$",
                                            "default": "",
                                            "description": "Virtual Interface IP to be used for management interface of contrail HA nodes"
                                        },
                                        "contrail_internal_virtual_router_id": {
                                            "type": "integer",
                                            "default": 103,
                                            "description": "VRID for control/data interface HA functionality."
                                        }
                                    }
                                },
                                "database": {
                                    "type": "object",
                                    "properties": {
                                        "ip_port": {
                                            "type": "integer",
                                            "default": 9160,
                                            "description": "Port number used by database service."
                                        },
                                        "directory": {
                                            "type": "string",
                                            "default": "/var/lib/cassandra",
                                            "description": "Dataabse directory path for Cassandra to use"
                                        },
                                        "minimum_diskGB": {
                                            "type": "integer",
                                            "pattern": "number",
                                            "default": 32,
                                            "description": "Minimum free disk size needed (in GB)"
                                        }
                                    }
                                },
                                "analytics": {
                                    "type": "object",
                                    "properties": {
                                        "data_ttl": {
                                            "type": "integer",
                                            "pattern": "number",
                                            "default": 48,
                                            "description": "Analytics Data TTL in hours"
                                        },
                                        "config_audit_ttl": {
                                            "type": "integer",
                                            "default": 2160,
                                            "description": "Analytics config audit TTL in hours"
                                        },
                                        "statistics_ttl": {
                                            "type": "integer",
                                            "default": 168,
                                            "description": "Analytics statistics TTL in hours"
                                        },
                                        "flow_ttl": {
                                            "type": "integer",
                                            "default": 2,
                                            "description": "Analytics flow TTL in hours"
                                        },
                                        "snmp_scan_frequency": {
                                            "type": "integer",
                                            "default": 600,
                                            "description": "SNMP scan interval in seconds"
                                        },
                                        "snmp_fast_scan_frequency": {
                                            "type": "integer",
                                            "default": 60,
                                            "description": "SNMP fast scan interval in seconds"
                                        },
                                        "topology_scan_frequency": {
                                            "type": "integer",
                                            "default": 60,
                                            "description": "Topology scan interval in seconds"
                                        },
                                        "syslog_port": {
                                            "type": "integer",
                                            "default": -1,
                                            "description": "Analytics syslog port value"
                                        },
                                        "data_directory": {
                                            "type": "string",
                                            "default": "",
                                            "description": "Analytics dir name where data files are stored, default use the same value as database_dir in database role."
                                        },
                                        "ssd_data_directory": {
                                            "type": "string",
                                            "default": "",
                                            "description": "Analytics dir name where ssd files are stored, default use the same value as database_dir in database role."
                                        },
                                        "redis_password": {
                                            "type": "string",
                                            "default": null,
                                            "description": "Password to use for Redis service"
                                        }
                                    }
                                },
                                "control": {
                                    "type": "object",
                                    "properties": {
                                        "encapsulation_priority": {
                                            "type": "string",
                                            "default": "VXLAN,MPLSoUDP,MPLSoGRE",
                                            "description": "The priority order for tunnel encapsulation methods used by Controller EVPN"
                                        },
                                        "router_asn": {
                                            "type": "integer",
                                            "default": 64512,
                                            "description": "The ASN that the cluster belongs to"
                                        },
                                        "external_bgp": {
                                            "type": "string",
                                            "default": "",
                                            "description": "List of external BGP peers in the form of name, address tuples e.g. [('montreal', '13.1.0.254')]"
                                        }
                                    }
                                },
                                "config": {
                                    "type": "object",
                                    "properties": {
                                        "manage_neutron": {
                                            "type": "boolean",
                                            "default": true,
                                            "description": "Whether config manages neutron service"
                                        },
                                        "zookeeper_ip_port": {
                                            "type": "integer",
                                            "default": 2181,
                                            "description": "The IP Port that the zookeeper service listens on"
                                        },
                                        "healthcheck_interval": {
                                            "type": "integer",
                                            "default": 5,
                                            "description": "Discovery health check interval"
                                        },
                                        "amqp_use_ssl": {
                                            "type": "boolean",
                                            "default": false,
                                            "description": "Flag to enable or disable rabbitmq server SSL support for contrail config"
                                        }
                                    }
                                },
                                "webui": {
                                    "type": "object",
                                    "properties": {}
                                },
                                "compute": {
                                    "type": "object",
                                    "properties": {
                                        "huge_pages": {
                                            "type": "string",
                                            "default": "",
                                            "description": "Specify what percentage of host memory should be reserved for access with huge pages"
                                        },
                                        "core_mask": {
                                            "type": "string",
                                            "default": "",
                                            "description": "Specify CPU affinity mask to run vRouter with. Supports hexadecimal, comma-separated list of CPUs, dash-separated range of CPUs"
                                        },
                                        "sriov": {
                                            "type": "object",
                                            "properties": {
                                                "enable": {
                                                    "type": "boolean",
                                                    "default": false,
                                                    "description": "Flag to set if SRIOV is enabled"
                                                }
                                            }
                                        }
                                    }
                                },
                                "vmware": {
                                    "type": "object",
                                    "properties": {
                                        "ip": {
                                            "type": "string",
                                            "default": "",
                                            "description": "VMware IP address."
                                        },
                                        "username": {
                                            "type": "string",
                                            "default": "",
                                            "description": "VMware user name"
                                        },
                                        "password": {
                                            "type": "string",
                                            "default": "",
                                            "description": "VMware user password"
                                        },
                                        "vswitch": {
                                            "type": "string",
                                            "default": "",
                                            "description": "VMware vswitch name"
                                        }
                                    }
                                },
                                "vgw": {
                                    "type": "object",
                                    "properties": {
                                        "public_subnet": {
                                            "type": "string",
                                            "default": "",
                                            "description": "VGW public subnet address."
                                        },
                                        "public_vn_name": {
                                            "type": "string",
                                            "default": "",
                                            "description": "VGW public virtual network name."
                                        },
                                        "interface": {
                                            "type": "string",
                                            "default": "",
                                            "description": "VGW interface name"
                                        },
                                        "gateway_routes": {
                                            "type": "string",
                                            "default": "",
                                            "description": "VGW routes"
                                        }
                                    }
                                },
                                "storage": {
                                    "type": "object",
                                    "properties": {
                                        "storage_monitor_secret": {
                                            "type": "string",
                                            "default": "",
                                            "description": "Key for Storage monitor Secret"
                                        },
                                        "osd_bootstrap_key": {
                                            "type": "string",
                                            "default": "",
                                            "description": "OSD Bootstrap Key value"
                                        },
                                        "storage_chassis_config": {
                                            "type": "array",
                                            "items": {
                                                "type": "string"
                                            },
                                            "description": "Storage chassis config"
                                        },
                                        "live_migration_host": {
                                            "type": "string",
                                            "default": "",
                                            "description": "Live migration host IP"
                                        },
                                        "storage_admin_key": {
                                            "type": "string",
                                            "default": "",
                                            "description": "Ceph Storage admin key"
                                        }
                                    }
                                },
                                "toragent": {
                                    "type": "object",
                                    "properties": {}
                                },
                                "tsn": {
                                    "type": "object",
                                    "properties": {}
                                }
                            }
                        },
                        "openstack": {
                            "type": "object",
                            "properties": {
                                "keystone": {
                                    "type": "object",
