                },
                "health_check_abort": {
                    "type": "boolean",
                    "description": "Enable/disable abort upon health check failures",
                    "default": true
                },
                "validate_critical_roles": {
                    "type": "boolean",
                    "description": "Enable/disable critical role validation",
                    "default": true
                },
                "Juniper": {
                    "type": "object",
                    "additionalProperties": false,
                    "default": {},
                    "properties": {
                        "bgp": {
                            "type": "object",
                            "additionalProperties": false,
