{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "SSM model",
    "description": "Description of a state space model following the grammar of the SSM inference package",
    "definitions": {
        "require": {
            "type": "object",
            "properties": {
                "datapackage": {
                    "type": "string"
                },
                "resource": {
                    "type": "string"
                },
                "fields": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                }
            }
        }
    },
    "type": "object",
    "properties": {
        "populations": {
            "type": "array",
            "description": "Grouping of the state variables comprised in your compartmental model. For each group, provide a name and the list of corresponding states. By adding an optional remainder field, you will ensure the population size remains positive.",
            "items": {
                "type": "object",
                "properties": {
                    "name": {
                        "type": "string"
                    },
                    "composition": {
                        "type": "array",
                        "items": {
                            "type": "string"
                        }
                    },
                    "remainder": {
                        "type": "object",
                        "description": "Following this instruction, the value of the remainder variable at every time will be determined by the size of the population minus the sum of the other compartments. Note that SSM will discard scenarios where this variable becomes negative.",
                        "properties": {
                            "name": {
                                "type": "string"
                            },
                            "pop_size": {
                                "type": "string"
                            }
                        },
                        "required": [
                            "name",
                            "pop_size"
                        ]
                    }
                },
                "required": [
                    "name",
                    "composition"
                ]
            }
        },
        "reactions": {
            "type": "array",
            "description": "Description of the dynamics of your compartmental model. We only consider density-dependent reactions: each rate will be multiplied by the size of the compartment individuals are leaving. See the accumulators and white_noise optional fields for additional options.",
            "items": {
                "type": "object",
                "properties": {
                    "from": {
                        "type": "string"
                    },
                    "to": {
                        "type": "string"
                    },
                    "rate": {
                        "type": "string"
                    },
                    "description": {
                        "type": "string"
                    },
                    "white_noise": {
                        "type": "object",
                        "description": "In order to cope with the absence or mis-specification of environmental factors in the model, you can multiply the rate of each reaction by a white gamma noise. To correlate these noises, use the same name. For more information, see Breto et al. 2009, Time series analysis via mechanistic models.",
                        "properties": {
                            "name": {
                                "type": "string"
                            },
                            "sd": {
                                "type": "string"
                            }
                        },
                        "required": [
                            "name",
                            "sd"
                        ]
                    },
                    "accumulators": {
                        "type": "array",
                        "description": "When your are monitoring or fitting the integrated flow of a given reaction, you can store it in one or several variables defined in this list. If a given flow variable is repeated in several reactions, it will correspond of the sum of the flows of these reactions.",
                        "items": {
                            "type": "string"
                        }
                    },
                    "keywords": {
                        "type": "array",
                        "items": {
                            "type": "string"
                        }
                    }
                },
                "required": [
                    "from",
                    "to",
                    "rate"
                ]
            }
        },
        "sde": {
            "type": "object",
            "description": "System of stochastic differential equations, defined by their drift vector and dispersion matrix",
            "properties": {
                "drift": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "name": {
                                "type": "string",
                                "description": "State variable which dynamic is determined by this line of the system."
                            },
                            "f": {
                                "type": [
                                    "number",
                                    "string"
                                ],
                                "description": "Deterministic component of the equation."
                            },
                            "transformation": {
                                "type": "string",
                                "description": "In case you want to express the equation in terms of a function of X and avoid applying the Ito formula."
                            }
                        },
                        "required": [
                            "name",
                            "f"
                        ]
                    }
                },
                "dispersion": {
                    "type": "array",
                    "description": "Dispersion matrix L. It needs to have as many rows as objects in drifts, and as many colums as independent sources of noise.",
                    "items": {
                        "type": "array",
                        "items": {
                            "type": [
                                "number",
                                "string"
                            ]
                        }
                    }
                }
            },
            "required": [
                "drift",
                "dispersion"
            ]
        },
        "ode": {
            "type": "array",
            "description": "System of ordinary differential equations.",
            "items": {
                "type": "object",
                "properties": {
                    "name": {
                        "type": "string",
                        "description": "State variable which dynamic is determined by this line of the system."
                    },
                    "f": {
                        "type": [
                            "number",
                            "string"
                        ],
                        "description": "Deterministic component of the equation."
                    },
                    "transformation": {
                        "type": "string",
                        "description": "In case you want to express the equation in terms of a function of X and avoid applying the Ito formula."
                    }
                },
                "required": [
                    "name",
                    "f"
                ]
            }
        },
        "observations": {
            "type": "array",
            "description": "Name each of the observed time series, determine when observations started to be collected and what is the distribution of the observation process.",
            "items": {
                "type": "object",
                "properties": {
                    "name": {
                        "type": "string"
                    },
                    "start": {
                        "type": "string",
                        "format": "date-time"
                    },
                    "distribution": {
                        "type": "string"
                    },
                    "mean": {
                        "type": "string"
                    },
                    "sd": {
                        "type": "string"
                    },
                    "n": {
                        "type": "string"
                    },
                    "p": {
                        "type": "string"
                    }
                },
                "required": [
                    "name",
                    "start",
                    "distribution"
                ]
            }
        },
        "data": {
            "type": "array",
            "description": "Link each of the observed variables to a data resource.",
            "items": {
                "type": "object",
                "anyOf": [
                    {
                        "type": "object",
                        "properties": {
                            "name": {
                                "type": "string"
                            },
                            "description": {
                                "type": "string"
                            },
                            "require": {
                                "$ref": "#/definitions/require"
                            },
                            "transformation": {
                                "description": "When the parameters used in the model are functions of the data resources, specify the relation here.",
                                "type": "string"
                            }
                        },
                        "required": [
                            "name",
                            "require"
                        ]
                    }
                ]
            }
        },
        "inputs": {
            "type": "array",
            "description": "Link each of the parameters or covariates at stake in your model to a data resource.",
            "items": {
                "type": "object",
                "anyOf": [
                    {
                        "type": "object",
                        "properties": {
                            "name": {
                                "type": "string"
                            },
                            "description": {
                                "type": "string"
                            },
                            "require": {
                                "$ref": "#/definitions/require"
                            },
                            "transformation": {
                                "description": "When the parameters used in the model are functions of the data resources, specify the relation here.",
                                "type": "string"
                            },
                            "to_resource": {
                                "description": "In order to make predictions after fitting your data, specify how to invert the transformation relation at a later time than t0.",
                                "type": "string"
                            }
                        },
                        "required": [
                            "name"
                        ]
                    }
                ]
            }
        }
    }
}

{
    "id": "http://schemas.triniti.io/json-schema/gdbots/forms/field/number-field/1-0-0.json#",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "_schema": {
            "type": "string",
            "pattern": "^pbj:([a-z0-9-]+):([a-z0-9\\.-]+):([a-z0-9-]+)?:([a-z0-9-]+):([0-9]+-[0-9]+-[0-9]+)$",
            "default": "pbj:gdbots:forms:field:number-field:1-0-0"
        },
        "name": {
            "type": "string",
            "pattern": "^[a-zA-Z_]{1}[\\w-]*$",
            "description": "A unique identifier (within the form) for the field. This value is not shown to the user and should NOT change once set.",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "maps_to": {
            "type": "string",
            "default": "cf",
            "pattern": "^[a-zA-Z_]{1}\\w*$",
            "description": "The name of the schema field the answer will map to. By default this will go to the \"cf\" field which is a \"dynamic-field\" list containing all answers filled out on the form (ref \"gdbots:forms:mixin:send-submission\").",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "label": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "description": "The main text for the question/field.",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "placeholder": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "description": {
            "type": "string",
            "minLength": 0,
            "maxLength": 65535,
            "description": "A short description to better explain this field.",
            "pbj": {
                "type": "text",
                "rule": "single"
            }
        },
        "is_required": {
            "type": "boolean",
            "pbj": {
                "type": "boolean",
                "rule": "single"
            }
        },
        "link_text": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "description": "The text that will replace the token \"{link}\" within the label or description.",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "link_url": {
            "type": "string",
            "pattern": "^(https?:\\/\\/)?([\\da-z\\.-]+)\\.([a-z\\.]{2,6})([\\/\\w \\.-]*)*\\/?$",
            "description": "The URL to use for the replaced token \"{link}\" within the label or description.",
            "pbj": {
                "type": "string",
                "rule": "single",
                "format": "url"
            }
        },
        "pii_impact": {
            "type": "string",
            "enum": [
                "unknown",
                "high",
                "moderate",
                "low"
            ],
            "pbj": {
                "type": "string-enum",
                "rule": "single"
            }
        },
        "min_value": {
            "type": "integer",
            "default": 0,
            "minimum": 0,
            "maximum": 4294967295,
            "pbj": {
                "type": "int",
                "rule": "single"
            }
        },
        "max_value": {
            "type": "integer",
            "default": 0,
            "minimum": 0,
            "maximum": 4294967295,
            "pbj": {
                "type": "int",
                "rule": "single"
            }
        },
        "decimals": {
            "type": "integer",
            "default": 0,
            "minimum": 0,
            "maximum": 6,
            "description": "Number of decimal places to allow. A \"0\" denotes this number field will require an integer.",
            "pbj": {
                "type": "tiny-int",
                "rule": "single"
            }
        }
    },
    "required": [
        "_schema",
        "name"
    ],
    "additionalProperties": false
}

