        "absolute_path": {
            "description": "A path only. Query string and/or fragment are not allowed.",
            "type": "string",
            "pattern": "^/(([a-zA-Z0-9._~!$&'()*+,;=:@-]|%[0-9a-fA-F]{2})+(/([a-zA-Z0-9._~!$&'()*+,;=:@-]|%[0-9a-fA-F]{2})*)*)?$"
        },
        "access_limited": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "auth_bypass_ids": {
                    "description": "Deprecated: auth_bypass_ids should be sent as a separate field",
                    "$ref": "#/definitions/guid_list"
                },
                "organisations": {
                    "description": "A list of organisation content ids permitted access to this item",
                    "$ref": "#/definitions/guid_list"
                },
                "users": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    }
                }
            }
        },
        "analytics_identifier": {
            "description": "A short identifier we send to Google Analytics for multi-valued fields. This means we avoid the truncated values we would get if we sent the path or slug of eg organisations.",
            "anyOf": [
                {
                    "type": "string"
                },
                {
                    "type": "null"
                }
            ]
        },
        "body_html_and_govspeak": {
            "description": "The main content provided as HTML with the govspeak markdown it's rendered from",
            "anyOf": [
                {
                    "$ref": "#/definitions/multiple_content_types"
                }
            ]
        },
        "description_optional": {
            "anyOf": [
                {
                    "$ref": "#/definitions/description"
                },
                {
                    "type": "null"
                }
            ]
        },
        "details": {
            "type": "object",
            "required": [
                "start_button_text"
            ],
            "additionalProperties": false,
            "properties": {
                "body": {
                    "$ref": "#/definitions/body_html_and_govspeak"
                },
                "external_related_links": {
                    "$ref": "#/definitions/external_related_links"
                },
                "nodes": {
                    "description": "List of nodes consisting of questions and answers",
                    "type": "array",
                    "items": {
                        "description": "A node represents either a question or an answer and results in a renderable page",
                        "type": "object",
                        "required": [
                            "kind",
                            "slug",
                            "title"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "body": {
                                "$ref": "#/definitions/body_html_and_govspeak"
                            },
                            "kind": {
                                "enum": [
                                    "question",
                                    "outcome"
                                ]
                            },
                            "options": {
                                "description": "Contains references to other nodes",
                                "type": "array",
                                "items": {
                                    "description": "An option represents a possible answer a user can select which links to another node",
                                    "type": "object",
                                    "required": [
                                        "label",
                                        "slug",
                                        "next_node"
                                    ],
                                    "additionalProperties": false,
                                    "properties": {
                                        "label": {
                                            "type": "string"
                                        },
                                        "next_node": {
                                            "type": "string"
                                        },
                                        "slug": {
                                            "type": "string"
                                        }
                                    }
                                }
                            },
                            "slug": {
                                "type": "string"
                            },
                            "title": {
                                "type": "string"
                            }
                        }
                    }
                },
                "start_button_text": {
                    "$ref": "#/definitions/start_button_text"
                }
            }
        },
        "external_link": {
            "type": "object",
            "required": [
                "title",
                "url"
            ],
            "additionalProperties": false,
            "properties": {
                "title": {
                    "type": "string"
                },
                "url": {
                    "type": "string",
                    "format": "uri"
                }
            }
        },
        "external_related_links": {
