                    "$ref": "#/definitions/hex-color"
                },
                "fillColor1": {
                    "$ref": "#/definitions/hex-color"
                },
                "borderColor2": {
                    "$ref": "#/definitions/hex-color"
                },
                "fillColor2": {
                    "$ref": "#/definitions/hex-color"
                },
                "frameBorderColor": {
                    "$ref": "#/definitions/hex-color"
                },
                "frameFillColor": {
                    "$ref": "#/definitions/hex-color"
                },
                "stripeColorDark": {
                    "$ref": "#/definitions/hex-color"
                },
                "stripeColorLight": {
                    "$ref": "#/definitions/hex-color"
                },
                "gridColor": {
                    "$ref": "#/definitions/hex-color"
                }
            }
        },
        "tasks": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "start": {
                        "$ref": "#/definitions/date"
                    },
                    "end": {
                        "$ref": "#/definitions/date-or-placeholder"
                    },
                    "recur": {
                        "type": "number",
                        "minimum": 1,
                        "maximum": 365
                    },
                    "startTo": {
                        "type": "array",
                        "items": {
                            "type": "number",
                            "minimum": 1,
                            "maximum": 256
                        },
                        "minItems": 1,
                        "_uniqueItems": true
                    },
                    "endTo": {
                        "type": "array",
                        "items": {
                            "type": "number",
                            "minimum": 1,
                            "maximum": 256
                        },
