            "items": {
                "type": "string",
                "format": "textFile"
            }
        },
        "heroes": {
            "type": "array",
            "description": "List of configuration files for heroes",
            "items": {
                "type": "string",
                "format": "textFile"
            }
        },
        "objects": {
            "type": "array",
            "description": "List of configuration files for objects",
            "items": {
                "type": "string",
                "format": "textFile"
            }
        },
        "spells": {
            "type": "array",
            "description": "List of configuration files for spells",
            "items": {
                "type": "string",
                "format": "textFile"
            }
        },
        "skills": {
            "type": "array",
            "description": "List of configuration files for skills",
            "items": {
                "type": "string",
                "format": "textFile"
            }
        },
        "templates": {
            "type": "array",
            "description": "List of configuration files for RMG templates",
            "items": {
                "type": "string",
                "format": "textFile"
            }
