                    "$ref": "#/definitions/SeverityType"
                },
                "comment": {
                    "type": "string"
                },
                "from": {
                    "$ref": "#/definitions/ReachabilityFromRestrictionType"
                },
                "to": {
                    "$ref": "#/definitions/ReachabilityToRestrictionType"
                }
            }
        },
        "RequiredRuleType": {
